49	/* ── Local debug console ─────────────────────────────────────────────
50	 * The AP→CP RPMsg path (ui_rpmsg_server) is the production driver, but it
51	 * only fires once the AP agent link is up.  For on-device visual testing of
52	 * the pure-LVGL pages (pet ring / particle flow / chat cards) this console
53	 * accepts a small word set so each view and agent-state animation can be
54	 * exercised straight from the CP NSH, without the AP or a network.  Mirrors
55	 * the AP nsh_commands debug words (show_chat / set_pet / set_page) and adds
56	 * bubble injection so the chat-card color bars are verifiable too. */
57	
58	static void ui_print_help(void)
59	{
60	  syslog(LOG_INFO,
61	         "[%s] cmds: show | page <0|1> | pet <0-5> | ptype <0-4> | ptt <0|1|2> |\n"
62	         "       say <text> | sayc <hex> <text> | user <text> | demo | quit\n",
63	         TAG);
64	}
