66	static void ui_demo_sequence(void)
67	{
68	  syslog(LOG_INFO, "[%s] demo: pet states 0..5\n", TAG);
69	  lvgl_ui_channel_set_page(0);
70	  for (int st = 0; st <= 5; st++)
71	    {
72	      lvgl_ui_channel_set_pet_state(st);
73	      usleep(1500 * 1000);
74	    }
75	
76	  syslog(LOG_INFO, "[%s] demo: particle page (state mirrors pet)\n", TAG);
77	  lvgl_ui_channel_set_page(1);
78	  for (int st = 0; st <= 5; st++)
79	    {
80	      lvgl_ui_channel_set_pet_state(st);
81	      usleep(1200 * 1000);
82	    }
83	
84	  syslog(LOG_INFO, "[%s] demo: chat screen + 4 card color bars\n", TAG);
85	  lvgl_ui_channel_show();
86	  lvgl_ui_channel_send_user("帮我看看这个提交能不能合入");
87	  lvgl_ui_channel_send("这个提交已 MERGED，状态：正常合入");      /* 蓝 structured */
88	  lvgl_ui_channel_send("值得合入，建议采纳");                     /* 绿 conclusion */
89	  lvgl_ui_channel_send("Jira 经办人待确认，More Info");           /* 橙 jira */
90	  lvgl_ui_channel_send("这是一条普通回复，用于展示默认灰色色条"); /* 灰 plain */
91	
92	  syslog(LOG_INFO, "[%s] demo done → back to pet IDLE\n", TAG);
93	  lvgl_ui_channel_set_pet_state(0);
94	  lvgl_ui_channel_set_page(0);
95	}
