97	int main(int argc, FAR char *argv[])
98	{
99	  int ret;
100	
101	  syslog(LOG_INFO, "[%s] CP UI renderer starting (LCD/LVGL owner core)\n", TAG);
102	
103	  ret = lvgl_ui_channel_init();
104	  if (ret != 0)
105	    {
106	      syslog(LOG_ERR, "[%s] lvgl_ui_channel_init failed rc=%d\n", TAG, ret);
107	      return 1;
108	    }
109	
110	  ret = lvgl_ui_channel_start();
111	  if (ret != 0)
112	    {
113	      syslog(LOG_ERR, "[%s] lvgl_ui_channel_start failed rc=%d\n", TAG, ret);
114	      return 2;
115	    }
116	
117	#ifdef CONFIG_AI_AGENT_PET_STATUS
118	  /* M7 差异化页 (pure-LVGL 退路): show the pet status ring as the cold-start
119	   * home screen.  The chat screen is built but stays in the background; the
120	   * first incoming RPMsg message (or a SET_PET_STATE) drives the foreground.
121	   * Idle-yield (lvgl_ui_channel's timer) brings the pet back after a chat
122	   * conversation goes quiet.  No test bubble here — it would immediately
123	   * displace the pet home screen we want to demo. */
124	  pet_status_view_show();
125	  syslog(LOG_INFO, "[%s] pet status ring is the home screen\n", TAG);
126	#else
127	  /* Bring the chat screen to the foreground. */
128	  lvgl_ui_channel_show();
129	
130	  /* Smoke bubble: proves the chat-view + MiSans CJK font render on the
131	   * real CP+LCD. voice_channel_speak() is a no-op stub on this side. */
132	  lvgl_ui_channel_send("CP真机 UI 测试气泡：ai_agent 界面已点亮");
133	#endif
134	
135	  /* Open the AP→CP UI RPMsg endpoint.  Once the AP agent's link comes up,
136	   * bubbles/toasts it sends over RPMSG land here and are rendered by the
137	   * real lvgl_ui_channel_* / lvgl_toast_* on this core.  Idempotent. */
138	  ret = ui_rpmsg_server_init();
139	  if (ret != 0)
140	    {
141	      syslog(LOG_WARNING, "[%s] ui_rpmsg_server_init failed rc=%d "
142	                          "(CP renders locally; AP-driven bubbles disabled)\n",
143	             TAG, ret);
144	    }
145	
146	  syslog(LOG_INFO, "[%s] UI up; LVGL thread running. Type 'quit' to exit.\n",
147	         TAG);
148	
149	  /* The LVGL event-loop thread spawned by _start() is detached and keeps
150	   * rendering.  Keep this task alive so a manual NSH launch isn't reaped
151	   * and so the RPMsg-UI endpoint stays hosted.
152	   *
153	   * Ctrl-C is NOT a reliable exit here: in a flat build NSH does not deliver
154	   * SIGINT to the foreground builtin (CONFIG_TTY_SIGINT targets the
155	   * foreground group, but the builtin is not job-controlled by NSH).  So we
156	   * read stdin and quit on "quit"/"exit"/"q" — the foreground builtin owns
157	   * the console stdin, so this always reaches us, unlike the signal.  EOF
158	   * (stdin closed, e.g. launched with stdin redirected away) falls back to
159	   * pause() so the endpoint keeps being hosted. */
160	  for (;;)
161	    {
162	      char line[256];
163	      char cmd[32];
164	      char *s;
165	      char *arg;
166	      int n = 0;
167	      size_t len;
168	
169	      if (fgets(line, sizeof(line), stdin) == NULL)
170	        {
171	          /* stdin closed/unavailable — keep hosting the endpoint. */
172	          pause();
173	          continue;
174	        }
175	
176	      s = line;
177	      while (*s == ' ' || *s == '\t')
178	        {
179	          s++;
180	        }
181	      len = strlen(s);
182	      while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r'))
183	        {
184	          s[--len] = '\0';
185	        }
186	
187	      if (sscanf(s, "%31s%n", cmd, &n) != 1)
188	        {
189	          continue; /* empty line */
190	        }
191	      arg = s + n;
192	      while (*arg == ' ' || *arg == '\t')
193	        {
194	          arg++;
195	        }
196	
197	      if (strcmp(cmd, "quit") == 0 || strcmp(cmd, "exit") == 0 ||
198	          strcmp(cmd, "q") == 0)
199	        {
200	          syslog(LOG_INFO, "[%s] quit received; tearing down UI\n", TAG);
201	          break;
202	        }
203	      else if (strcmp(cmd, "help") == 0)
204	        {
205	          ui_print_help();
206	        }
207	      else if (strcmp(cmd, "show") == 0 || strcmp(cmd, "chat") == 0)
208	        {
209	          lvgl_ui_channel_show();
210	        }
211	      else if (strcmp(cmd, "page") == 0)
212	        {
213	          lvgl_ui_channel_set_page(atoi(arg));
214	        }
215	      else if (strcmp(cmd, "pet") == 0)
216	        {
217	          lvgl_ui_channel_set_pet_state(atoi(arg));
218	        }
219	      else if (strcmp(cmd, "ptype") == 0)
220	        {
221	          pet_status_view_set_type(atoi(arg));
222	        }
223	      else if (strcmp(cmd, "ptt") == 0)
224	        {
225	          lvgl_ui_channel_set_ptt(atoi(arg));
226	        }
227	      else if (strcmp(cmd, "user") == 0 && *arg)
228	        {
229	          lvgl_ui_channel_send_user(arg);
230	        }
231	      else if (strcmp(cmd, "sayc") == 0)
232	        {
233	          char *end = NULL;
234	          uint32_t color = (uint32_t)strtoul(arg, &end, 0);
235	          if (end && end != arg)
236	            {
237	              const char *txt = end;
238	              while (*txt == ' ' || *txt == '\t')
239	                {
240	                  txt++;
241	                }
242	              if (*txt)
243	                {
244	                  lvgl_ui_channel_send_ex(txt, color);
245	                }
246	            }
247	        }
248	      else if (strcmp(cmd, "say") == 0 && *arg)
249	        {
250	          lvgl_ui_channel_send(arg);
251	        }
252	      else if (strcmp(cmd, "demo") == 0)
253	        {
254	          ui_demo_sequence();
255	        }
256	      else
257	        {
258	          syslog(LOG_WARNING, "[%s] unknown cmd '%s' (help for list)\n",
259	                 TAG, cmd);
260	        }
261	    }
262	
263	  /* Graceful teardown (schedules widget deletion in the LVGL thread,
264	   * waits up to 2s).  Safe to skip on exit, but exercising the path
265	   * also verifies lvgl_ui_channel_stop works on real CP. */
266	  lvgl_ui_channel_stop();
267	  syslog(LOG_INFO, "[%s] UI stopped; returning to NSH\n", TAG);
268	
269	  return 0;
270	}
