948	/* Heap-allocated state for async set_ptt (single int fits in a void* but
949	 * keep a small struct for clarity/future fields). */
950	typedef struct {
951	    int state;
952	} async_ptt_t;
953	
954	static void set_ptt_async_cb(void* data)
955	{
956	    async_ptt_t* p = (async_ptt_t*)data;
957	    if (!p) {
958	        return;
959	    }
960	    if (!s_state.initialized || !s_state.running) {
961	        free(p);
962	        return;
963	    }
964	
965	    switch (p->state) {
966	    case LVGL_UI_PTT_RECORDING:
967	        s_state.is_recording = true;
968	        s_state.is_processing = false;
969	        recording_indicator_start();
970	#ifdef CONFIG_AI_AGENT_PET_STATUS
971	        /* Mirror PTT onto the pet: a recording session reads as "listening". */
972	        pet_status_view_set_state(PET_STATE_LISTENING);
973	#endif
974	        break;
975	    case LVGL_UI_PTT_PROCESSING:
976	        s_state.is_recording = false;
977	        s_state.is_processing = true;
978	        recording_indicator_show_processing();
979	#ifdef CONFIG_AI_AGENT_PET_STATUS
980	        pet_status_view_set_state(PET_STATE_THINKING);
981	#endif
982	        break;
983	    case LVGL_UI_PTT_IDLE:
984	    default:
985	        s_state.is_recording = false;
986	        s_state.is_processing = false;
987	        recording_indicator_stop();
988	#ifdef CONFIG_AI_AGENT_PET_STATUS
989	        pet_status_view_set_state(PET_STATE_IDLE);
990	#endif
991	        break;
992	    }
993	    free(p);
994	}
