996	int lvgl_ui_channel_set_ptt(int state)
997	{
998	    async_ptt_t* payload;
999	
1000	    if (!s_state.initialized || !s_state.running) {
1001	        return -EINVAL;
1002	    }
1003	    /* Coerce unknown values to IDLE. */
1004	    if (state != LVGL_UI_PTT_IDLE && state != LVGL_UI_PTT_RECORDING &&
1005	        state != LVGL_UI_PTT_PROCESSING) {
1006	        state = LVGL_UI_PTT_IDLE;
1007	    }
1008	
1009	    payload = malloc(sizeof(async_ptt_t));
1010	    if (!payload) {
1011	        syslog(LOG_ERR, "[%s] set_ptt: payload alloc failed\n", TAG);
1012	        return -ENOMEM;
1013	    }
1014	    payload->state = state;
1015	    lv_async_call(set_ptt_async_cb, payload);
1016	    return 0;
1017	}
