1372	static void ptt_btn_event_cb(lv_event_t* e)
1373	{
1374	    lv_event_code_t code = lv_event_get_code(e);
1375	
1376	    /* Single-click toggle: first click starts recording, second stops */
1377	    if (code != LV_EVENT_CLICKED) {
1378	        return;
1379	    }
1380	
1381	    pthread_mutex_lock(&s_state.lock);
1382	
1383	    if (s_state.is_processing) {
1384	        pthread_mutex_unlock(&s_state.lock);
1385	        return;
1386	    }
1387	
1388	    if (!s_state.is_recording) {
1389	        /* First click: start recording */
1390	        int ret = voice_channel_start();
1391	        if (ret != 0) {
1392	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
1393	            pthread_mutex_unlock(&s_state.lock);
1394	            chat_view_add_message("录音启动失败", false, 0);
1395	            return;
1396	        }
1397	
1398	        s_state.is_recording = true;
1399	        pthread_mutex_unlock(&s_state.lock);
1400	
1401	        recording_indicator_start();
1402	    } else {
1403	        /* Second click: stop recording and process */
1404	        s_state.is_recording = false;
1405	        s_state.is_processing = true;
1406	        pthread_mutex_unlock(&s_state.lock);
1407	
1408	        recording_indicator_show_processing();
1409	
1410	        /* Stop recording and get ASR text synchronously */
1411	        char asr_text[LVGL_UI_MSG_MAX_LEN];
1412	        int ret = voice_channel_stop_with_text(asr_text,
1413	            sizeof(asr_text));
1414	
1415	        if (ret != 0) {
1416	            syslog(LOG_ERR,
1417	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
1418	                TAG, ret);
1419	            goto done;
1420	        }
1421	
1422	        if (asr_text[0] == '\0') {
1423	            chat_view_add_message("未识别到语音", false, 0);
1424	            goto done;
1425	        }
1426	
1427	        /* Route through the single dispatch point so the destination stays
1428	         * out of this file: with no sink registered the utterance goes to the
1429	         * chat bus exactly as before, and a product that registered one owns
1430	         * it instead.  This file must not learn which consumer exists.
1431	         */
1432	
1433	        voice_channel_dispatch(asr_text);
1434	        chat_view_add_message(asr_text, true, 0);
1435	
1436	    done:
1437	        pthread_mutex_lock(&s_state.lock);
1438	        s_state.is_processing = false;
1439	        pthread_mutex_unlock(&s_state.lock);
1440	        recording_indicator_stop();
1441	    }
1442	}
