1445	 * selector argument, so we cannot cast it directly as exec_cb. */
1446	static void anim_opa_cb(void* obj, int32_t v)
1447	{
1448	    lv_obj_set_style_opa((lv_obj_t*)obj, (lv_opa_t)v, 0);
