1451	/* Water-ripple idle shimmer for the "请说" pill.  Two independent animators
1452	 * run on distinct periods so the effect reads as a soft surface undulation
1453	 * rather than a mechanical blink:
1454	 *   water_opa_cb   — opacity breathes 255..190 (the surface dims/brightens)
1455	 *   water_shadow_cb — the orange glow widens/narrows (light spreading outward)
1456	 * Recording swaps the opacity anim for the red rec pulse; the glow keeps
1457	 * rippling throughout. */
1458	static void water_opa_cb(void* obj, int32_t v)
1459	{
