106	{
107	  int ret;
108	
109	  pthread_mutex_lock(&g_ptt_lock);
110	  if (g_ptt_busy || g_ptt_recording)
111	    {
112	      pthread_mutex_unlock(&g_ptt_lock);
113	      return;  /* ignore re-press during an active session */
114	    }
115	  g_ptt_recording = true;
116	  pthread_mutex_unlock(&g_ptt_lock);
117	
118	  ret = voice_channel_start();
119	  if (ret != 0)
120	    {
121	      syslog(LOG_ERR, "[%s] voice_channel_start failed rc=%d\n", TAG, ret);
122	      pthread_mutex_lock(&g_ptt_lock);
123	      g_ptt_recording = false;
124	      pthread_mutex_unlock(&g_ptt_lock);
125	      return;
126	    }
127	
128	#if PTT_HAVE_UI
129	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_RECORDING);
130	#endif
131	  syslog(LOG_INFO, "[%s] PTT press → recording\n", TAG);
132	}
133	
134	static void ptt_on_release(void)
135	{
136	  char asr_text[CONFIG_AI_AGENT_PTT_ASR_CAP];
137	  int ret;
138	  bool asr_failed = false;
139	
140	  pthread_mutex_lock(&g_ptt_lock);
141	  if (!g_ptt_recording)
142	    {
143	      /* release without a matched press (e.g. baseline edge) — ignore */
144	      pthread_mutex_unlock(&g_ptt_lock);
145	      return;
146	    }
147	  g_ptt_recording = false;
148	  g_ptt_busy = true;
149	  pthread_mutex_unlock(&g_ptt_lock);
150	
151	#if PTT_HAVE_UI
152	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_PROCESSING);
153	#endif
154	  syslog(LOG_INFO, "[%s] PTT release → ASR\n", TAG);
155	
156	  /* Blocks until ASR finalizes the stream.  Fine here — dedicated thread. */
157	  asr_text[0] = '\0';
158	  ret = voice_channel_stop_with_text(asr_text, sizeof(asr_text));
159	  if (ret != 0)
160	    {
161	      syslog(LOG_ERR, "[%s] voice_channel_stop_with_text failed rc=%d\n",
162	             TAG, ret);
163	      asr_failed = true;
164	      goto done;
165	    }
166	
167	  if (asr_text[0] == '\0')
168	    {
169	      syslog(LOG_WARNING, "[%s] no speech recognized\n", TAG);
170	      goto done;
171	    }
172	
173	  syslog(LOG_INFO, "[%s] recognized: %s\n", TAG, asr_text);
174	
175	#if PTT_HAVE_UI
176	  /* Echo the user utterance as a right-aligned bubble on CP. */
177	  (void)lvgl_ui_channel_send_user(asr_text);
178	#endif
179	
180	  /* Route to the agent (message_bus → LLM → reply bubble + TTS).
181	   * voice_channel_dispatch is the single sink point; on AP it is real. */
182	  voice_channel_dispatch(asr_text);
183	
184	done:
185	  pthread_mutex_lock(&g_ptt_lock);
186	  g_ptt_busy = false;
187	  pthread_mutex_unlock(&g_ptt_lock);
188	
189	#if PTT_HAVE_UI
190	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_IDLE);
191	  /* On ASR failure, drive the pet to ERROR (5) AFTER the PTT-IDLE mirror so
192	   * the RPMsg FIFO delivers ERROR last — the pet shows red+shake instead of
193	   * silently going idle-green.  pet_status_view.h: 5=PET_STATE_ERROR. */
194	  if (asr_failed)
195	    (void)lvgl_ui_channel_set_pet_state(5);
196	#endif
197	}
