199	static void* ptt_button_thread(void* arg)
200	{
201	  const char* devpath = CONFIG_AI_AGENT_PTT_DEVPATH;
202	  struct btn_pollevents_s pe;
203	  struct pollfd pfd;
204	  btn_buttonset_t supported;
205	  btn_buttonset_t last;
206	  bool have_baseline = false;
207	  int fd;
208	  int bit = ptt_button_bit();
209	
210	  (void)arg;
211	
212	  fd = open(devpath, O_RDONLY);
213	  if (fd < 0)
214	    {
215	      syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
216	      return NULL;
217	    }
218	
219	  supported = 0;
220	  if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0)
221	    {
222	      syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
223	      close(fd);
224	      return NULL;
225	    }
226	
227	  if ((supported & (btn_buttonset_t)bit) == 0)
228	    {
229	      syslog(LOG_ERR, "[%s] button idx %d not in supported set 0x%08lx\n",
230	             TAG, CONFIG_AI_AGENT_PTT_BUTTON_IDX, (unsigned long)supported);
231	      close(fd);
232	      return NULL;
233	    }
234	
235	  /* Wake on both edges of our PTT button only. */
236	  pe.bp_press   = (btn_buttonset_t)bit;
237	  pe.bp_release = (btn_buttonset_t)bit;
238	  (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
239	
240	  pfd.fd     = fd;
241	  pfd.events = POLLIN;
242	  last       = 0;
243	
244	  syslog(LOG_INFO, "[%s] watching %s button %d (hold-to-talk)\n", TAG,
245	         devpath, CONFIG_AI_AGENT_PTT_BUTTON_IDX);
246	
247	  for (;;)
248	    {
249	      btn_buttonset_t cur;
250	      btn_buttonset_t change;
251	      ssize_t nread;
252	
253	      if (poll(&pfd, 1, -1) < 0)
254	        {
255	          if (errno == EINTR)
256	            {
257	              continue;
258	            }
259	          syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
260	          break;
261	        }
262	
263	      if ((pfd.revents & POLLIN) == 0)
264	        {
265	          continue;
266	        }
267	
268	      nread = read(fd, &cur, sizeof(cur));
269	      if (nread != (ssize_t)sizeof(cur))
270	        {
271	          continue;
272	        }
273	
274	      if (!have_baseline)
275	        {
276	          last = cur;
277	          have_baseline = true;
278	          continue;
279	        }
280	
281	      change = cur ^ last;
282	      if ((change & (btn_buttonset_t)bit) == 0)
283	        {
284	          last = cur;
285	          continue;  /* our button didn't change */
286	        }
287	
288	      if (cur & (btn_buttonset_t)bit)
289	        {
290	          ptt_on_press();
291	        }
292	      else
293	        {
294	          ptt_on_release();
295	        }
296	      last = cur;
297	    }
298	
299	  close(fd);
300	  return NULL;
301	}
