303	int ptt_button_start(void)
304	{
305	  pthread_t tid;
306	  pthread_attr_t attr;
307	  struct sched_param sp;
308	  int ret;
309	
310	  if (g_ptt_running)
311	    {
312	      return 0;
313	    }
314	
315	  ret = pthread_attr_init(&attr);
316	  if (ret != 0)
317	    {
318	      syslog(LOG_ERR, "[%s] attr_init: %d\n", TAG, ret);
319	      return -ret;
320	    }
321	  sp.sched_priority = CONFIG_AI_AGENT_PTT_PRIORITY;
322	  (void)pthread_attr_setschedpolicy(&attr, SCHED_RR);
323	  (void)pthread_attr_setschedparam(&attr, &sp);
324	  (void)pthread_attr_setstacksize(&attr, CONFIG_AI_AGENT_PTT_STACKSIZE);
325	
326	  ret = pthread_create(&tid, &attr, ptt_button_thread, NULL);
327	  (void)pthread_attr_destroy(&attr);
328	  if (ret != 0)
329	    {
330	      syslog(LOG_ERR, "[%s] pthread_create: %d\n", TAG, ret);
331	      return -ret;
332	    }
333	
334	  pthread_detach(tid);
335	  g_ptt_running = true;
336	  syslog(LOG_INFO, "[%s] PTT button thread started\n", TAG);
337	  return 0;
338	}
