void cmd_remote_once(void)
{
    if (remote_ctrl_channel_decide(REMOTE_DECISION_ONCE) != OK) {
        printf("No approvable request is pending (or one was already "
               "answered).\n");
        return;
    }

    printf("Approved once.\n");
}

