17	/**
18	 * ui_rpmsg_client.c — AP-side shim that implements the lvgl_ui_channel_* +
19	 * lvgl_toast_* API as RPMsg messages to the CP core (路 B).
20	 *
21	 * The AP core runs ai_agent (LLM/voice/TLS) but has no LCD/LVGL/FPU.  Instead
22	 * of building bubbles locally, this shim serializes each UI call into a
23	 * ui_rpmsg_msg and sends it over a dedicated RPMsg endpoint to the CP core,
24	 * where ui_rpmsg_server.c deserializes it and calls the REAL LVGL functions.
25	 *
26	 * Compile-time selection (CMakeLists): when CONFIG_AI_AGENT_UI_RPMSG is set
27	 * (AP), the agent links this file INSTEAD of lvgl_ui_channel.c/lvgl_toast.c.
28	 * The call sites in agent_main.c / nsh_commands.c / remote_ctrl_channel.c /
29	 * notify_service.c are guarded with
30	 *     #if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
31	 * so the same source compiles on both cores unchanged.
32	 *
33	 * TTS split: the original lvgl_ui_channel_send() renders a bubble AND calls
34	 * voice_channel_speak() for TTS.  On the real device TTS hardware lives on
35	 * AP, so this shim calls voice_channel_speak() locally (real, audible) and
36	 * separately sends UI_RPMSG_SEND to CP for the bubble.  CP's copy of
37	 * lvgl_ui_channel_send() calls voice_channel_speak() too, but on CP that is
38	 * the cp_stubs.c no-op — so audio plays once (on AP) and the bubble renders
39	 * once (on CP), with no protocol round-trip for audio.
40	 *
41	 * Mirrors the RPMsg endpoint pattern in
42	 * chips/bk7258/mb_ipc/bk_mailbox_rpmsg.c: rpmsg_register_callback →
43	 * rpmsg_create_ept(name, ANY, ANY) → rpmsg_send_offchannel_raw.  Flat build
44	 * makes the kernel rpmsg symbols linkable from this userspace builtin.
45	 */
