230	/* ── RPMsg device appear/disappear callbacks ─────────────────────────── */
231	
232	static void ui_rpmsg_server_created(struct rpmsg_device *rdev, void *priv)
233	{
234	  struct ui_rpmsg_server_state *s = priv;
235	  int ret;
236	
237	  if (strcmp(rpmsg_get_cpuname(rdev), UI_RPMSG_PEER_CPU) != 0 || s->created)
238	    {
239	      return;
240	    }
241	
242	  ret = rpmsg_create_ept(&s->ept, rdev, UI_RPMSG_EPT_NAME,
243	                         RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
244	                         ui_rpmsg_server_rx, NULL);
245	  if (ret < 0)
246	    {
247	      syslog(LOG_ERR, "[%s] rpmsg_create_ept failed: %d\n", TAG, ret);
248	      return;
249	    }
250	
251	  s->created = true;
252	  syslog(LOG_INFO, "[%s] endpoint up ← AP agent UI commands\n", TAG);
253	}
254	
255	static void ui_rpmsg_server_destroyed(struct rpmsg_device *rdev, void *priv)
256	{
257	  struct ui_rpmsg_server_state *s = priv;
258	
259	  if (s->created &&
260	      strcmp(rpmsg_get_cpuname(rdev), UI_RPMSG_PEER_CPU) == 0)
261	    {
262	      rpmsg_destroy_ept(&s->ept);
263	      s->created = false;
264	      syslog(LOG_WARNING, "[%s] endpoint down (AP agent gone)\n", TAG);
265	    }
266	}
267	
268	/* ── public init (called from cp_ui_main) ────────────────────────────── */
269	
270	int ui_rpmsg_server_init(void)
271	{
272	  int ret;
273	
274	  if (g_ui_srv.registered)
275	    {
276	      return 0;
277	    }
278	
279	  g_ui_srv.registered = true;
280	  ret = rpmsg_register_callback(&g_ui_srv, ui_rpmsg_server_created,
281	                                ui_rpmsg_server_destroyed, NULL, NULL);
282	  if (ret < 0)
283	    {
284	      g_ui_srv.registered = false;
285	      syslog(LOG_ERR, "[%s] rpmsg_register_callback failed: %d\n", TAG, ret);
286	      return ret;
287	    }
288	
289	  syslog(LOG_INFO, "[%s] registered; waiting for AP UI link\n", TAG);
290	  return 0;
291	}
