108	/* ── Data structures ──────────────────────────────────────────── */
109	
110	/* Single chat message */
111	typedef struct {
112	    char text[LVGL_UI_MSG_MAX_LEN]; /* Message text, truncated to 512 bytes */
113	    bool is_user; /* true = user message, false = Agent reply */
114	    lv_obj_t* bubble; /* Corresponding LVGL bubble widget */
115	} chat_msg_t;
116	
117	/* Chat history ring buffer */
118	typedef struct {
119	    chat_msg_t msgs[CHAT_HISTORY_MAX]; /* Ring buffer slots */
120	    int head; /* Next write position */
121	    int count; /* Current message count */
122	} chat_history_t;
123	
124	/* LVGL UI channel internal state */
125	typedef struct {
126	    bool initialized;
127	    bool running;
128	    pthread_mutex_t lock;
129	
130	    /* UI widget references */
131	    lv_obj_t* screen;
132	    lv_obj_t* chat_list;
133	    lv_obj_t* ptt_btn;
134	    lv_obj_t* ptt_label;
135	    lv_obj_t* rec_indicator;
136	    lv_anim_t rec_anim;
137	    lv_anim_t water_anim;         /* "请说" idle water-ripple opacity pulse */
138	    lv_anim_t water_shadow_anim;  /* "请说" idle water-ripple glow pulse */
139	
140	    /* Chat history */
141	    chat_history_t history;
142	
143	    /* PTT state */
144	    bool is_recording;
145	    bool is_processing;
146	
147	    /* Screen visibility */
148	    bool screen_visible;
149	
150	    /* Previous screen to restore on stop */
151	    lv_obj_t* prev_screen;
152	
153	} lvgl_ui_state_t;
154	
155	static lvgl_ui_state_t s_state;
156	
157	/* ── Self-managed LVGL init (qemu: no miwear/launcher owns LVGL) ──
158	 *
159	 * On real hardware the miwear/launcher process initializes LVGL and
160	 * owns the display + event loop; this channel only creates widgets.
161	 * On qemu-arm64-v8a-ap there is no such process, so the channel must
162	 * bring up LVGL itself: lv_init() + lv_nuttx_init(/dev/fb0) + a
163	 * lv_timer_handler() loop thread.  s_lv_owned tracks whether WE did
164	 * the init so stop() can deinit symmetrically. */
165	static bool s_lv_owned = false;
166	static pthread_t s_lv_loop_tid;
167	static volatile bool s_lv_loop_running = false;
168	static lv_nuttx_result_t s_lv_result;
169	
170	static void* lv_loop_thread(void* arg)
171	{
172	    (void)arg;
173	    while (s_lv_loop_running) {
174	        uint32_t idle = lv_timer_handler();
175	        if (idle == 0)
176	            idle = 1;
177	        usleep(idle * 1000);
178	    }
179	    return NULL;
180	}
181	
182	/* ── Async message payload for lv_async_call ──────────────── */
183	
