210	/**
211	 * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
212	 * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
213	 * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
214	 * trims back to the last complete character.  Always NUL-terminates.
215	 *
216	 * This prevents a half-cut Chinese char from rendering as a replacement glyph
217	 * at the end of a truncated Agent reply.
218	 */
219	static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
220	{
221	    if (dst_size == 0) return;
222	    size_t n = strnlen(src, dst_size - 1);
223	    memcpy(dst, src, n);
224	    dst[n] = '\0';
225	
226	    /* If we filled the buffer, the last char may be incomplete.  Walk back
227	     * from the end to find a UTF-8 leading byte and check its expected length
228	     * against the remaining bytes. */
229	    if (n < dst_size - 1) return;          /* src fit fully, no truncation */
230	    size_t i = n;
231	    while (i > 0) {
232	        unsigned char c = (unsigned char)dst[i - 1];
233	        if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
234	        i--;
235	    }
236	    if (i == 0) return;                     /* all continuation bytes? give up */
237	    unsigned char lead = (unsigned char)dst[i - 1];
238	    size_t need;
239	    if      ((lead & 0x80) == 0x00) need = 1;   /* ASCII */
240	    else if ((lead & 0xE0) == 0xC0) need = 2;
241	    else if ((lead & 0xF0) == 0xE0) need = 3;
242	    else if ((lead & 0xF8) == 0xF0) need = 4;
243	    else { dst[i - 1] = '\0'; return; }         /* invalid lead, cut it */
244	    if (n - (i - 1) < need) {

