1374	static void ptt_btn_event_cb(lv_event_t* e)
1375	{
1376	    lv_event_code_t code = lv_event_get_code(e);
1377	
1378	    /* Single-click toggle: first click starts recording, second stops */
1379	    if (code != LV_EVENT_CLICKED) {
1380	        return;
1381	    }
1382	
1383	    pthread_mutex_lock(&s_state.lock);
1384	
1385	    if (s_state.is_processing) {
1386	        pthread_mutex_unlock(&s_state.lock);
1387	        return;
1388	    }
1389	
1390	    if (!s_state.is_recording) {
1391	        /* First click: start recording */
1392	        int ret = voice_channel_start();
1393	        if (ret != 0) {
1394	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
1395	            pthread_mutex_unlock(&s_state.lock);
1396	            chat_view_add_message("录音启动失败", false, 0);
1397	            return;
1398	        }
1399	
1400	        s_state.is_recording = true;
1401	        pthread_mutex_unlock(&s_state.lock);
1402	
1403	        recording_indicator_start();
1404	    } else {
1405	        /* Second click: stop recording and process */
1406	        s_state.is_recording = false;
1407	        s_state.is_processing = true;
1408	        pthread_mutex_unlock(&s_state.lock);
1409	
1410	        recording_indicator_show_processing();
1411	
1412	        /* Stop recording and get ASR text synchronously */
1413	        char asr_text[LVGL_UI_MSG_MAX_LEN];
1414	        int ret = voice_channel_stop_with_text(asr_text,
1415	            sizeof(asr_text));
1416	
1417	        if (ret != 0) {
1418	            syslog(LOG_ERR,
1419	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
1420	                TAG, ret);
1421	            goto done;
1422	        }
1423	
1424	        if (asr_text[0] == '\0') {
1425	            chat_view_add_message("未识别到语音", false, 0);
1426	            goto done;
1427	        }
1428	
1429	        /* Route through the single dispatch point so the destination stays
1430	         * out of this file: with no sink registered the utterance goes to the
1431	         * chat bus exactly as before, and a product that registered one owns
1432	         * it instead.  This file must not learn which consumer exists.
1433	         */
1434	
1435	        voice_channel_dispatch(asr_text);
1436	        chat_view_add_message(asr_text, true, 0);
1437	
1438	    done:
1439	        pthread_mutex_lock(&s_state.lock);
1440	        s_state.is_processing = false;
1441	        pthread_mutex_unlock(&s_state.lock);
1442	        recording_indicator_stop();
1443	    }
1444	}
