1453	/* Water-ripple idle shimmer for the "请说" pill.  Two independent animators
1454	 * run on distinct periods so the effect reads as a soft surface undulation
1455	 * rather than a mechanical blink:
1456	 *   water_opa_cb   — opacity breathes 255..190 (the surface dims/brightens)
1457	 *   water_shadow_cb — the orange glow widens/narrows (light spreading outward)
1458	 * Recording swaps the opacity anim for the red rec pulse; the glow keeps
1459	 * rippling throughout. */
1460	static void water_opa_cb(void* obj, int32_t v)
1461	{
1462	    lv_opa_t opa = LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100;
1463	    lv_obj_set_style_opa((lv_obj_t*)obj, opa, 0);
1464	}
