  memset(&m, 0, sizeof(m));
  m.op = UI_RPMSG_SCROLL;
  m.payload[0] = (uint8_t)dir;
  m.payload_len = 1;

  ret = ui_rpmsg_send(&m);
  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] scroll to CP failed: %d\n", TAG, ret);
    }
  return ret;
}

