690	        s_state.ptt_btn = NULL;
691	        s_state.ptt_label = NULL;
692	        s_state.rec_indicator = NULL;
693	    }
694	
695	    sem_destroy(&s_stop_sem);
696	
697	    /* Destroy the mutex */
698	    pthread_mutex_destroy(&s_state.lock);
699	
