204	/**
205	 * Copy text into a fixed buffer with UTF-8-aware truncation.  Copies at most
206	 * dst_size-1 bytes, then if the cut lands inside a multi-byte UTF-8 sequence
207	 * (leading byte 0xC0..0xF4 not followed by enough continuation bytes 0x80..0xBF),
208	 * trims back to the last complete character.  Always NUL-terminates.
209	 *
210	 * This prevents a half-cut Chinese char from rendering as a replacement glyph
211	 * at the end of a truncated Agent reply.
212	 */
213	static void chat_view_copy_text(char* dst, const char* src, size_t dst_size)
214	{
215	    if (dst_size == 0) return;
216	    size_t n = strnlen(src, dst_size - 1);
217	    memcpy(dst, src, n);
218	    dst[n] = '\0';
219	
220	    /* If we filled the buffer, the last char may be incomplete.  Walk back
221	     * from the end to find a UTF-8 leading byte and check its expected length
222	     * against the remaining bytes. */
223	    if (n < dst_size - 1) return;          /* src fit fully, no truncation */
224	    size_t i = n;
225	    while (i > 0) {
226	        unsigned char c = (unsigned char)dst[i - 1];
227	        if ((c & 0xC0) != 0x80) break;     /* not a continuation byte */
228	        i--;
229	    }

860	        return -EINVAL;
861	    }
862	    if (!s_state.initialized || !s_state.running) {
863	        syslog(LOG_ERR, "[%s] send_user: channel not ready\n", TAG);
864	        return -EINVAL;
865	    }
866	
867	    if (!s_state.screen_visible) {
868	        lvgl_ui_channel_show();
869	    }
870	
871	    payload = malloc(sizeof(async_msg_t));
872	    if (!payload) {
873	        syslog(LOG_ERR, "[%s] send_user: payload alloc failed\n", TAG);
874	        return -ENOMEM;
875	    }
876	    chat_view_copy_text(payload->text, text, LVGL_UI_MSG_MAX_LEN);
877	    payload->is_user = true;
878	    payload->bar_color = 0;
879	
880	    lv_async_call(chat_view_add_message_async_cb, payload);
881	    return 0;
882	}
