1310	static void ptt_btn_event_cb(lv_event_t* e)
1311	{
1312	    lv_event_code_t code = lv_event_get_code(e);
1313	
1314	    /* Single-click toggle: first click starts recording, second stops */
1315	    if (code != LV_EVENT_CLICKED) {
1316	        return;
1317	    }
1318	
1319	    pthread_mutex_lock(&s_state.lock);
1320	
1321	    if (s_state.is_processing) {
1322	        pthread_mutex_unlock(&s_state.lock);
1323	        return;
1324	    }
1325	
1326	    if (!s_state.is_recording) {
1327	        /* First click: start recording */
1328	        int ret = voice_channel_start();
1329	        if (ret != 0) {
1330	            syslog(LOG_ERR, "[%s] voice_channel_start failed (rc=%d)\n", TAG, ret);
1331	            pthread_mutex_unlock(&s_state.lock);
1332	            chat_view_add_message("录音启动失败", false, 0);
1333	            return;
1334	        }
1335	
1336	        s_state.is_recording = true;
1337	        pthread_mutex_unlock(&s_state.lock);
1338	
1339	        recording_indicator_start();
1340	    } else {
1341	        /* Second click: stop recording and process */
1342	        s_state.is_recording = false;
1343	        s_state.is_processing = true;
1344	        pthread_mutex_unlock(&s_state.lock);
1345	
1346	        recording_indicator_show_processing();
1347	
1348	        /* Stop recording and get ASR text synchronously */
1349	        char asr_text[LVGL_UI_MSG_MAX_LEN];
1350	        int ret = voice_channel_stop_with_text(asr_text,
1351	            sizeof(asr_text));
1352	
1353	        if (ret != 0) {
1354	            syslog(LOG_ERR,
1355	                "[%s] voice_channel_stop_with_text failed (rc=%d)\n",
1356	                TAG, ret);
1357	            goto done;
1358	        }
1359	
1360	        if (asr_text[0] == '\0') {
1361	            chat_view_add_message("未识别到语音", false, 0);
1362	            goto done;
1363	        }
1364	
1365	        /* Route through the single dispatch point so the destination stays
1366	         * out of this file: with no sink registered the utterance goes to the
1367	         * chat bus exactly as before, and a product that registered one owns
1368	         * it instead.  This file must not learn which consumer exists.
1369	         */
1370	
1371	        voice_channel_dispatch(asr_text);
1372	        chat_view_add_message(asr_text, true, 0);
1373	
1374	    done:
1375	        pthread_mutex_lock(&s_state.lock);
1376	        s_state.is_processing = false;
1377	        pthread_mutex_unlock(&s_state.lock);
1378	        recording_indicator_stop();
1379	    }
1380	}
