457	     *   bot_m   0 — chat_list bottom flush with the round-face bottom edge
458	     *               (y=260) */
459	    int32_t side_m   = (round_d * 6)  / 100;   /* chat_list side gutter */
460	    int32_t top_m    = (round_d * 14) / 100;   /* chat_list top gutter */
461	    int32_t bot_m    = 0;                       /* chat_list bottom gutter */
