38	static const char* TAG = "remote_ctrl";
39	
40	/* ── State ─────────────────────────────────────────────────────────── */
41	
42	static struct remote_session_s g_session;
43	
44	static char g_broker_host[REMOTE_MQTT_HOST_MAX + 1];
45	static char g_broker_port[REMOTE_MQTT_PORT_MAX + 1];
46	static char g_username[REMOTE_MQTT_USER_MAX + 1];
47	static char g_password[REMOTE_MQTT_PASSWORD_MAX + 1];
48	static char g_device_id[REMOTE_MQTT_DEVICE_ID_MAX + 1];
49	static char g_topic_prefix[REMOTE_MQTT_TOPIC_PREFIX_MAX + 1];
50	
51	static bool g_configured;
52	static bool g_started;
