54	/* Turn completion, separate from the session's own lock.
55	 *
56	 * Lock order is one-way: the event handler runs with the session lock held and
57	 * then takes g_turn_lock, so no path may hold g_turn_lock while calling into
58	 * the session. remote_ctrl_channel_prompt() therefore arms the wait, submits
59	 * with no lock held, and only then blocks. */
60	static pthread_mutex_t g_turn_lock = PTHREAD_MUTEX_INITIALIZER;
61	static pthread_cond_t g_turn_cond = PTHREAD_COND_INITIALIZER;
62	static bool g_turn_pending;
63	static bool g_turn_finished;
64	
65	/* Who started the in-flight turn. `rask` (submit, async) wants the remote
66	 * reply mirrored onto the chat surfaces (console card + LVGL + TTS, the same
67	 * treatment an `ask` reply gets) because nobody is holding its hand. The LLM
68	 * tool path (prompt, sync) returns the reply as a tool result and the local
69	 * LLM presents its own answer through that path already — mirroring would
70	 * show everything twice. Set by each submit entry point before the turn
71	 * starts, read once when the transcript lands. */
72	static bool g_mirror_turn;
73	
74	/* ── Event handler ─────────────────────────────────────────────────── */
75	
76	static void notify_observer_state(const char *text);
77	static void notify_observer_reply(const char *text);
78	
79	/* Invoked by the session with its lock held: keep this cheap and never call
80	 * back into remote_session_*. */
81	static void on_session_event(void* context, enum remote_event_e event,
82	    const char* text)
83	{
84	    (void)context;
85	
86	    switch (event) {
87	    case REMOTE_EVENT_STATE:
88	        /* A status line and nothing else: what the agent is doing, never what it
89	         * said. The bridge holds to the same rule on its side, so this reports
90	         * "Agent working", a tool name, or "Agent replying" — the reply itself
91	         * arrives as REMOTE_EVENT_TURN_TRANSCRIPT once the turn ends.
92	         *
93	         * The prefix is what makes the line readable. A bare tool name or a
94	         * bare tool argument says nothing about which of those it is, and the
95	         * approval line is the one a person must react to right now -- it
96	         * names the key. */
97	        {
98	            const char *tag = "[状态]";
99	            char body[160];
100	
101	            if (text != NULL && strncmp(text, "approval required: ", 19) == 0) {
102	                tag = "[需要审批]";
103	                snprintf(body, sizeof(body),
104	                         "%s   ->  按 KEY1 批准 / KEY2 拒绝", text + 19);
105	            } else if (text != NULL && strstr(text, "completed") != NULL) {
106	                tag = "[工具]";
107	                snprintf(body, sizeof(body), "%s", text);
108	            } else if (text != NULL &&
109	                       (strcmp(text, "Agent working") == 0 ||
110	                        strcmp(text, "Agent replying") == 0)) {
111	                tag = "[任务]";
112	                snprintf(body, sizeof(body), "%s",
113	                         strcmp(text, "Agent working") == 0 ? "进行中" : "回复中");
114	            } else if (text != NULL && strncmp(text, "Agent turn", 10) == 0) {
115	                tag = "[任务]";
116	                snprintf(body, sizeof(body), "%s", text + 11);
117	            } else {
118	                snprintf(body, sizeof(body), "%s", text != NULL ? text : "");
119	            }
120	
121	            syslog(LOG_INFO, "[%s] %s %s\n", TAG, tag, body);
122	            notify_observer_state(text);
123	        }
124	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
125	        /* A permission request parks the turn until a human decides, and the
126	         * console log line is easy to miss — surface it on the toast the
127	         * notify service uses, naming the two human-only commands. */
128	        if (text != NULL && strncmp(text, "approval required: ", 19) == 0) {
129	            char body[112];
130	            snprintf(body, sizeof(body), "ronce / rdeny: %s", text + 19);
131	            lvgl_toast_show_async("Approval", body, 0xff9800, 8000);
132	        }
133	#endif
134	        break;
135	
136	    case REMOTE_EVENT_AGENT_OUTPUT:
137	        /* Deliberately silent. A chunk lands every few tens of milliseconds and
138	         * splits mid-sentence, so logging one line per chunk filled the console
139	         * without saying anything the 'Agent replying' status line above has not
140	         * already said. The link accumulates them; the reply prints once, below. */
141	        break;
142	
143	    case REMOTE_EVENT_TURN_TRANSCRIPT:
144	        /* One call for the whole reply, not one per line. nx_vsyslog stamps its
145	         * prefix once per call, so printing line by line turned a reply into a
146	         * column of timestamped log records; passing the text in one go lets its
147	         * own newlines through and it reads as the block it is.
148	         *
149	         * No trailing newline here: nx_vsyslog appends one when the text does not
150	         * already end in it, so adding one would leave a blank line behind every
151	         * reply. Length is not a concern — CONFIG_SYSLOG_BUFFER is off on this
152	         * board, so the raw stream writes straight through with no fixed buffer
153	         * to truncate against. */
154	        /* agent_main.c already prints the reply to the console.  Logging
155	         * the whole body here printed it a second time on a board where
156	         * syslog shares that console.
157	         */
158	
159	        syslog(LOG_INFO, "[%s] reply %u bytes\n", TAG,
160	            text != NULL ? (unsigned)strlen(text) : 0u);
161	        notify_observer_reply(text);
162	        /* rask-initiated turns also ride the cli outbound branch so the reply
163	         * lands where an `ask` reply lands: console card, LVGL chat view and
164	         * the voice pipeline behind it. Cheap by design — one heap copy and a
165	         * ring-buffer push; no remote_session_* reentry. `rreply` still reads
166	         * the session transcript, so nothing is lost if the push fails. */
167	        if (g_mirror_turn && text != NULL && text[0] != '\0') {
168	            agent_msg_t msg;
169	            memset(&msg, 0, sizeof(msg));
170	            strncpy(msg.channel, "cli", sizeof(msg.channel) - 1);
171	            msg.content = strdup(text);
172	            if (msg.content != NULL) {
173	                if (message_bus_push_outbound(&msg) != OK)
174	                    free(msg.content);
175	            }
176	            g_mirror_turn = false;
177	        }
178	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
179	        /* A remote coding turn runs for minutes and the user walked away —
180	         * the approval toast (above) already owns the "needs you" case; this
181	         * one says the wait is over. Voice is already covered by the mirror
182	         * branch, so the toast only needs the first line of the reply. */
183	        if (text != NULL && text[0] != '\0') {
184	            char body[112];
185	            snprintf(body, sizeof(body), "任务完成: %s", text);
186	            char* nl = strchr(body, '\n');
187	            if (nl != NULL)
188	                *nl = '\0';
189	            lvgl_toast_show_async("远程编码", body, 0x4caf50, 4000);
190	        }
191	#endif
192	        break;
193	
194	    case REMOTE_EVENT_OUTPUT_GAP:
195	        syslog(LOG_WARNING, "[%s] agent output may be incomplete\n", TAG);
196	        break;
197	
198	    case REMOTE_EVENT_MODEL:
199	        /* Announced because it can change from the PC side too, and which model
200	         * answered a prompt is worth knowing without polling 'rstat'. */
201	        syslog(LOG_INFO, "[%s] model: %s\n", TAG, text != NULL ? text : "");
202	        break;
203	
204	    case REMOTE_EVENT_PROMPT_REJECTED:
205	        pthread_mutex_lock(&g_turn_lock);
206	        g_turn_finished = true;
207	        pthread_cond_broadcast(&g_turn_cond);
208	        pthread_mutex_unlock(&g_turn_lock);
209	        syslog(LOG_WARNING, "[%s] prompt rejected by bridge\n", TAG);
210	        break;
211	
212	    case REMOTE_EVENT_TURN_RESULT:
213	        pthread_mutex_lock(&g_turn_lock);
214	        g_turn_finished = true;
215	        pthread_cond_broadcast(&g_turn_cond);
216	        pthread_mutex_unlock(&g_turn_lock);
217	        syslog(LOG_INFO, "[%s] %s\n", TAG, text != NULL ? text : "turn ended");
218	        break;
219	
220	    case REMOTE_EVENT_BILLING:
221	        syslog(LOG_INFO, "[%s] %s\n", TAG, text != NULL ? text : "");
222	        break;
223	
224	    case REMOTE_EVENT_SESSIONS:
225	        /* One write for the whole block (header + rows + footer included), so
226	         * it lands exactly like `rstat`'s box. The cached copy is never
227	         * printed by the command — this is the single print site. */
228	        if (text != NULL && text[0] != '\0') {
229	            printf("%s", text);
230	        }
231	        break;
232	
233	    default:
234	        break;
235	    }
236	}
