240	/* Splits "host" or "host:port"; the port defaults to the MQTT standard. */
241	static void parse_broker(const char* broker)
242	{
243	    const char* colon = strrchr(broker, ':');
244	    size_t host_length;
245	
246	    if (colon != NULL && colon != broker) {
247	        host_length = (size_t)(colon - broker);
248	        if (host_length > REMOTE_MQTT_HOST_MAX) {
249	            host_length = REMOTE_MQTT_HOST_MAX;
250	        }
251	        memcpy(g_broker_host, broker, host_length);
252	        g_broker_host[host_length] = '\0';
253	        snprintf(g_broker_port, sizeof(g_broker_port), "%.*s",
254	            (int)sizeof(g_broker_port) - 1, colon + 1);
255	    } else {
256	        snprintf(g_broker_host, sizeof(g_broker_host), "%s", broker);
257	        snprintf(g_broker_port, sizeof(g_broker_port), "%d",
258	            AGENT_MQTT_DEFAULT_PORT);
259	    }
260	}
