262	/* ── Transport thread ──────────────────────────────────────────────── */
263	
264	static void* transport_task(void* arg)
265	{
266	    struct remote_mqtt_config_s config;
267	
268	    (void)arg;
269	
270	    memset(&config, 0, sizeof(config));
271	    config.host = g_broker_host;
272	    config.port = g_broker_port;
273	    config.username = g_username;
274	    config.password = g_password;
275	    config.device_id = g_device_id;
276	    config.topic_prefix = g_topic_prefix[0] != '\0' ? g_topic_prefix : NULL;
277	
278	    /* Blocks until remote_ctrl_channel_stop(). */
279	    remote_link_mqtt_run(&config, &g_session);
280	    return NULL;
281	}
