285	int remote_ctrl_channel_init(void)
286	{
287	    char broker[REMOTE_MQTT_HOST_MAX + REMOTE_MQTT_PORT_MAX + 2];
288	
289	    memset(broker, 0, sizeof(broker));
290	    memset(g_broker_host, 0, sizeof(g_broker_host));
291	    memset(g_broker_port, 0, sizeof(g_broker_port));
292	    memset(g_username, 0, sizeof(g_username));
293	    memset(g_password, 0, sizeof(g_password));
294	    memset(g_device_id, 0, sizeof(g_device_id));
295	    memset(g_topic_prefix, 0, sizeof(g_topic_prefix));
296	    g_configured = false;
297	    g_started = false;
298	
299	    /* Credentials come from the config store, never from argv: a password in a
300	     * command line is visible in the process list. */
301	    claw_config_get(AGENT_CFG_KEY_REMOTE_BROKER, broker, sizeof(broker));
302	    claw_config_get(AGENT_CFG_KEY_REMOTE_DEVICE_ID, g_device_id,
303	        sizeof(g_device_id));
304	    claw_config_get(AGENT_CFG_KEY_REMOTE_USERNAME, g_username,
305	        sizeof(g_username));
306	    claw_config_get(AGENT_CFG_KEY_REMOTE_PASSWORD, g_password,
307	        sizeof(g_password));
308	    claw_config_get(AGENT_CFG_KEY_REMOTE_TOPIC_PREFIX, g_topic_prefix,
309	        sizeof(g_topic_prefix));
310	
311	    /* The session is usable before any link exists: it simply reports Offline
312	     * and refuses every outbound operation. */
313	    remote_session_init(&g_session, "");
314	    remote_session_set_event_handler(&g_session, on_session_event, NULL);
315	
316	    if (broker[0] == '\0') {
317	        syslog(LOG_INFO, "[%s] no remote_broker configured, channel idle\n",
318	            TAG);
319	        return OK;
320	    }
321	
322	    if (g_device_id[0] == '\0') {
323	        snprintf(g_device_id, sizeof(g_device_id), "%s", AGENT_NODE_ID);
324	    }
325	
326	    parse_broker(broker);
327	    g_configured = true;
328	
329	    syslog(LOG_INFO, "[%s] initialized (broker=%s:%s device=%s)\n", TAG,
330	        g_broker_host, g_broker_port, g_device_id);
331	    return OK;
332	}
