334	/* Voice is a control input to this channel, not a chat message: an
335	 * utterance from a PTT button is an instruction for the remote agent, the
336	 * same thing `rask` sends.  Deliberately remote_ctrl_channel_submit() and
337	 * not decide() -- the voice path never produces a permission decision, it
338	 * produces a prompt that later demands one, so the "a permission decision
339	 * is a human typing ronce/rdeny" rule stays intact and no keyword table or
340	 * intent classifier is needed.
341	 */
342	
343	static void voice_sink_to_remote(const char* text, void* ctx)
344	{
345	    char reply[256];
346	
347	    (void)ctx;
348	
349	    /* Non-blocking for the same reason `rask` is: a turn that stops for a
350	     * remote permission request has to leave the console and the button
351	     * adapter free to answer it.
352	     */
353	
354	    if (remote_ctrl_channel_submit(text, reply, sizeof(reply)) != OK) {
355	        syslog(LOG_ERR, "[%s] voice submit: %s\n", TAG, reply);
356	    }
357	}
