359	int remote_ctrl_channel_start(void)
360	{
361	    int ret;
362	
363	    if (!g_configured) {
364	        return OK;
365	    }
366	
367	    if (g_started) {
368	        return OK;
369	    }
370	
371	    ret = agent_task_create(transport_task, "remote_ctrl",
372	        AGENT_REMOTE_CTRL_STACK, NULL, AGENT_REMOTE_CTRL_PRIO);
373	    if (ret != OK) {
374	        syslog(LOG_ERR, "[%s] failed to create transport thread\n", TAG);
375	        return ERROR;
376	    }
377	
378	    g_started = true;
379	
380	    /* Registering here, not in init(), is what keeps this optional: an
381	     * unconfigured channel never claims the voice text, so a board that
382	     * only wants voice chat keeps the chat-bus default untouched.
383	     */
384	
385	    voice_channel_register_sink(voice_sink_to_remote, NULL);
386	    syslog(LOG_INFO, "[%s] started (voice sink registered)\n", TAG);
387	    return OK;
388	}
389	
390	void remote_ctrl_channel_stop(void)
391	{
392	    if (!g_started) {
393	        return;
394	    }
395	
396	    remote_link_mqtt_stop();
397	    g_started = false;
398	
399	    /* Release anyone blocked in remote_ctrl_channel_prompt(). */
400	    pthread_mutex_lock(&g_turn_lock);
401	    g_turn_finished = true;
402	    pthread_cond_broadcast(&g_turn_cond);
403	    pthread_mutex_unlock(&g_turn_lock);
404	
405	    syslog(LOG_INFO, "[%s] stop requested\n", TAG);
406	}
