569	/* Turns a refused submit into something a person or a model can act on. The
570	 * session refuses for several distinct reasons and they need different
571	 * responses, so "failed" on its own would be useless. */
572	static void describe_submit_failure(const char* text, char* out,
573	    size_t out_size)
574	{
575	    struct remote_status_s status;
576	    char problem[192];
577	
578	    remote_session_status(&g_session, &status);
579	
580	    if (status.state == REMOTE_STATE_OFFLINE) {
581	        snprintf(out, out_size, "Error: remote agent link is offline");
582	    } else if (status.has_prompt) {
583	        snprintf(out, out_size,
584	            "Error: the remote agent is waiting for a permission decision on "
585	            "this device; answer it before sending a new prompt");
586	    } else if (status.turn_active) {
587	        snprintf(out, out_size, "Error: a remote turn is already running");
588	    } else if (!status.chat_supported) {
589	        snprintf(out, out_size,
590	            "Error: the remote bridge does not offer chat turns");
591	    } else if (!status.chat_epoch_current) {
592	        /* remote_link_can_submit_prompt() also requires chat_epoch == epoch.
593	         * A bridge reconnect refreshes epoch but leaves chat_epoch on the
594	         * old value until the next chat advertisement, and the turn was
595	         * refused with the generic "rejected locally" until this case had
596	         * a name of its own.
597	         */
598	
599	        snprintf(out, out_size,
600	            "Error: the chat channel is not bound to this connection yet "
601	            "(bridge reconnected?); try again in a moment");
602	    } else if (remote_prompt_text_problem(text, problem, sizeof(problem))) {
603	        /* Remaining refusals are about the text itself.  Name the check it
604	         * failed: "empty or too long or bad UTF-8" sent people looking at
605	         * the length of a 32-byte prompt that had lost a byte on the
606	         * console.
607	         */
608	
609	        snprintf(out, out_size, "Error: %s", problem);
610	    } else {
611	        snprintf(out, out_size, "Error: the prompt was refused locally");
612	    }
613	}
614	
615	int remote_ctrl_channel_submit(const char* text, char* out, size_t out_size)
616	{
617	    if (text == NULL || out == NULL || out_size == 0) {
618	        return ERROR;
619	    }
620	
621	    if (!g_configured) {
622	        snprintf(out, out_size, "Error: remote control is not configured");
623	        return ERROR;
624	    }
625	
626	    /* Deliberately does not touch the blocking-wait state: the session's own
627	     * turn reservation is what keeps two turns from overlapping, and nothing
628	     * would clear a wait that no one is performing. */
629	    if (!remote_session_submit_prompt(&g_session, text)) {
630	        describe_submit_failure(text, out, out_size);
631	        return ERROR;
632	    }
633	    /* The submit succeeded, so the turn that is starting belongs to rask:
634	     * mirror its transcript onto the chat surfaces when it lands. */
635	    g_mirror_turn = true;
636	
637	    snprintf(out, out_size,
638	        "Prompt sent. Use 'rstat' for progress; the reply prints in one piece "
639	        "when the turn ends, and 'rreply' re-reads it.");
640	    return OK;
641	}
642	
643	int remote_ctrl_channel_transcript(char* out, size_t out_size)
644	{
645	    if (out == NULL || out_size == 0 || !g_configured) {
646	        return ERROR;
647	    }
648	
649	    return remote_session_transcript(&g_session, out, out_size) ? OK : ERROR;
650	}
651	
652	int remote_ctrl_channel_prompt(const char* text, uint32_t timeout_ms,
653	    char* out, size_t out_size)
654	{
655	    struct timespec deadline;
656	    bool finished;
657	    int ret = OK;
658	
659	    if (text == NULL || out == NULL || out_size == 0) {
660	        return ERROR;
661	    }
662	
663	    if (!g_configured) {
664	        snprintf(out, out_size, "Error: remote control is not configured");
665	        return ERROR;
666	    }
667	
668	    /* Only one caller may own the turn slot at a time. The session would refuse
669	     * a second submit anyway; rejecting here keeps the waiters unambiguous. */
670	    pthread_mutex_lock(&g_turn_lock);
671	    if (g_turn_pending) {
672	        pthread_mutex_unlock(&g_turn_lock);
673	        snprintf(out, out_size, "Error: a remote turn is already in progress");
674	        return ERROR;
675	    }
676	    /* Armed before submitting so a turn that completes immediately cannot be
677	     * missed between the submit and the wait. */
678	    g_turn_pending = true;
679	    g_turn_finished = false;
680	    /* The LLM presents its own answer built from the tool result; a mirrored
681	     * raw transcript on top of that would say everything twice. */
682	    g_mirror_turn = false;
683	    pthread_mutex_unlock(&g_turn_lock);
684	
685	    if (!remote_session_submit_prompt(&g_session, text)) {
686	        pthread_mutex_lock(&g_turn_lock);
687	        g_turn_pending = false;
688	        pthread_mutex_unlock(&g_turn_lock);
689	
690	        describe_submit_failure(text, out, out_size);
691	        return ERROR;
692	    }
693	
694	    clock_gettime(CLOCK_REALTIME, &deadline);
695	    deadline.tv_sec += (time_t)(timeout_ms / 1000);
696	    deadline.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
697	    if (deadline.tv_nsec >= 1000000000L) {
698	        deadline.tv_sec += 1;
699	        deadline.tv_nsec -= 1000000000L;
700	    }
701	
702	    pthread_mutex_lock(&g_turn_lock);
703	    while (!g_turn_finished) {
704	        if (pthread_cond_timedwait(&g_turn_cond, &g_turn_lock, &deadline) == ETIMEDOUT) {
705	            break;
706	        }
707	    }
708	    finished = g_turn_finished;
709	    g_turn_pending = false;
710	    pthread_mutex_unlock(&g_turn_lock);
711	
712	    if (!remote_session_transcript(&g_session, out, out_size)) {
713	        snprintf(out, out_size,
714	            "Error: remote agent output does not fit the tool buffer");
715	        return ERROR;
716	    }
717	
718	    if (!finished) {
719	        struct remote_status_s status;
720	
721	        remote_session_status(&g_session, &status);
722	
723	        /* A turn stalled on a permission request is an expected outcome, not a
724	         * failure: only a human on this device can release it. */
725	        if (status.has_prompt) {
726	            size_t used = strlen(out);
727	
728	            snprintf(out + used, out_size - used,
729	                "%s[The remote agent is waiting for approval of %s on this "
730	                "device. It cannot continue until someone answers.]",
731	                used > 0 ? "\n" : "", status.prompt.tool);
732	        } else {
733	            size_t used = strlen(out);
734	
735	            snprintf(out + used, out_size - used,
736	                "%s[The remote turn is still running; output so far is above.]",
737	                used > 0 ? "\n" : "");
738	        }
739	        ret = OK;
740	    }
741	
742	    if (out[0] == '\0') {
743	        snprintf(out, out_size, "The remote agent produced no text output.");
744	    }
745	
746	    return ret;
747	}
