/*
 * key_manager.c — AP-side S2/S3 context-sensitive keys (路 B M5).
 *
 * S1 is hold-to-talk (ptt_button.c).  This thread opens its own /dev/btn0
 * descriptor (button_upper.c's bu_open is a linked list, so multiple opens
 * coexist) and watches the two remaining user keys S2 (bit 1) and S3 (bit 2)
 * for short/long press edges, then dispatches:
 *
 *   short → context action: if a remote permission request is pending, the
 *           press is an approval decision (S2 = once, S3 = deny) and dismisses
 *           the approval page; otherwise it scrolls the chat transcript
 *           (S2 = up/older, S3 = down/newer).
 *   long  → S2 cycles the remote agent's model; S3 opens a fresh session.
 *
 * A long press is still edge-driven: the duration is measured between the
 * press and release edges in this single thread, so no separate timer is
 * needed and the release always lands on the same thread that saw the press.
 *
 * Only compiled under CONFIG_AI_AGENT_KEYMGR.  Remote-control calls are
 * guarded by CONFIG_AI_AGENT_REMOTE_CTRL and UI calls by LVGL_UI/UI_RPMSG,
 * so the same source builds whether or not the remote channel is present.
 */

#include <nuttx/config.h>

#ifdef CONFIG_AI_AGENT_KEYMGR

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/ioctl.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#include <nuttx/input/buttons.h>

#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
#include "ui/lvgl_ui_channel.h"
#include "ui/lvgl_toast.h"
#define KEYMGR_HAVE_UI 1
#else
#define KEYMGR_HAVE_UI 0
#endif

#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
#include "channels/remote_ctrl_channel.h"
#endif

#define TAG "key_manager"

#ifndef CONFIG_AI_AGENT_KEYMGR_DEVPATH
#  define CONFIG_AI_AGENT_KEYMGR_DEVPATH "/dev/btn0"
#endif

/* Physical button indexes: S2 = bit 1, S3 = bit 2 (S1 = bit 0 is the PTT). */
#define KEYMGR_IDX_S2 1
#define KEYMGR_IDX_S3 2

/* Hold longer than this to trigger the long-press action. */
#ifndef CONFIG_AI_AGENT_KEYMGR_LONG_MS
#  define CONFIG_AI_AGENT_KEYMGR_LONG_MS 800
#endif

#ifndef CONFIG_AI_AGENT_KEYMGR_STACKSIZE
#  define CONFIG_AI_AGENT_KEYMGR_STACKSIZE 8192
#endif

#ifndef CONFIG_AI_AGENT_KEYMGR_PRIORITY
#  define CONFIG_AI_AGENT_KEYMGR_PRIORITY 100
#endif

static bool g_key_running = false;

/* Per-key press timestamp, indexed by physical button index (1..2). */
static uint64_t g_press_ms[3];
static bool g_held[3];

static inline uint64_t key_now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
}

static inline btn_buttonset_t key_bit(int idx)
{
    return (btn_buttonset_t)(1u << idx);
}

/* ── short press: context action ───────────────────────────────────── */

static void key_short_press(int idx)
{
#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
    /* A pending permission request redefines the short press: S2 approves
     * once, S3 denies.  The approval page (driven by remote_ctrl_channel's
     * on_session_event) has already told the user this is the live meaning. */
    struct remote_status_s st;
    if (remote_ctrl_channel_status(&st) == OK && st.has_prompt) {
        enum remote_decision_e d = (idx == KEYMGR_IDX_S2)
                                     ? REMOTE_DECISION_ONCE
                                     : REMOTE_DECISION_DENY;
        (void)remote_ctrl_channel_decide(d);
#if KEYMGR_HAVE_UI
        /* Dismiss the page immediately — the bridge snapshot that clears the
         * prompt can lag, and the user just saw their decision registered. */
        (void)lvgl_ui_channel_clear_approval();
#endif
        syslog(LOG_INFO, "[%s] S%d short → %s\n", TAG, idx,
               d == REMOTE_DECISION_ONCE ? "approve-once" : "deny");
        return;
    }
#endif

#if KEYMGR_HAVE_UI
    /* No approval: scroll the chat transcript. S2 up (older), S3 down (newer). */
    int dir = (idx == KEYMGR_IDX_S2) ? 0 : 1;
    (void)lvgl_ui_channel_scroll(dir);
    syslog(LOG_INFO, "[%s] S%d short → scroll %s\n", TAG, idx,
           dir == 0 ? "up" : "down");
#else
    syslog(LOG_INFO, "[%s] S%d short (no UI channel)\n", TAG, idx);
#endif
}

/* ── long press: model / session ───────────────────────────────────── */

static void key_long_press(int idx)
{
    if (idx == KEYMGR_IDX_S2) {
#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
        /* Cycle to the next model the bridge offers.  The list is display-only
         * authority: the bridge still validates the name, so a stale entry is
         * refused rather than silently misapplied. */
        static struct remote_model_view_s mv;
        if (remote_ctrl_channel_model_view(&mv) == OK && mv.count > 0) {
            int cur = -1;
            int i;
            for (i = 0; i < mv.count; i++) {
                if (strcmp(mv.options[i], mv.current) == 0) {
                    cur = i;
                    break;
                }
            }
            int next = (cur + 1) % mv.count;
            (void)remote_ctrl_channel_select_model(mv.options[next]);
#if KEYMGR_HAVE_UI
            char body[REMOTE_MODEL_MAX + 16];
            snprintf(body, sizeof(body), "model: %s", mv.options[next]);
            lvgl_toast_show_async("Model", body, 0x4caf50, 2500);
#endif
            syslog(LOG_INFO, "[%s] S2 long → model %s\n", TAG, mv.options[next]);
        } else {
            syslog(LOG_WARNING, "[%s] S2 long → no model list\n", TAG);
        }
#else
        syslog(LOG_INFO, "[%s] S2 long (remote ctrl off)\n", TAG);
#endif
    } else {
#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
        (void)remote_ctrl_channel_new_session();
#if KEYMGR_HAVE_UI
        lvgl_toast_show_async("Session", "new session", 0x4caf50, 2500);
#endif
        syslog(LOG_INFO, "[%s] S3 long → new session\n", TAG);
#else
        syslog(LOG_INFO, "[%s] S3 long (remote ctrl off)\n", TAG);
#endif
    }
}

/* ── watch thread ──────────────────────────────────────────────────── */

static void* key_manager_thread(void* arg)
{
    const char* devpath = CONFIG_AI_AGENT_KEYMGR_DEVPATH;
    btn_buttonset_t mask = key_bit(KEYMGR_IDX_S2) | key_bit(KEYMGR_IDX_S3);
    struct btn_pollevents_s pe;
    struct pollfd pfd;
    btn_buttonset_t supported;
    btn_buttonset_t last;
    bool have_baseline = false;
    int fd;
    int i;

    (void)arg;

    fd = open(devpath, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
        return NULL;
    }

    supported = 0;
    if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0) {
        syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
        close(fd);
        return NULL;
    }
    if ((supported & mask) != mask) {
        syslog(LOG_ERR, "[%s] S2/S3 not all in supported set 0x%08lx\n",
               TAG, (unsigned long)supported);
        close(fd);
        return NULL;
    }

    pe.bp_press   = mask;
    pe.bp_release = mask;
    (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);

    pfd.fd     = fd;
    pfd.events = POLLIN;
    last       = 0;

    syslog(LOG_INFO, "[%s] watching %s S2/S3 (context keys)\n", TAG, devpath);

    for (;;) {
        btn_buttonset_t cur;
        btn_buttonset_t change;
        ssize_t nread;

        if (poll(&pfd, 1, -1) < 0) {
            if (errno == EINTR) {
                continue;
            }
            syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
            break;
        }
        if ((pfd.revents & POLLIN) == 0) {
            continue;
        }

        nread = read(fd, &cur, sizeof(cur));
        if (nread != (ssize_t)sizeof(cur)) {
            continue;
        }
        if (!have_baseline) {
            last = cur;
            have_baseline = true;
            continue;
        }

        change = cur ^ last;
        for (i = KEYMGR_IDX_S2; i <= KEYMGR_IDX_S3; i++) {
            btn_buttonset_t bit = key_bit(i);
            if ((change & bit) == 0) {
                continue;
            }
            if (cur & bit) {
                g_held[i] = true;
                g_press_ms[i] = key_now_ms();
            } else {
                if (!g_held[i]) {
                    continue;
                }
                g_held[i] = false;
                uint64_t dur = key_now_ms() - g_press_ms[i];
                if (dur >= CONFIG_AI_AGENT_KEYMGR_LONG_MS) {
                    key_long_press(i);
                } else {
                    key_short_press(i);
                }
            }
        }
        last = cur;
    }

    close(fd);
    return NULL;
}

int key_manager_start(void)
{
    pthread_t tid;
    pthread_attr_t attr;
    struct sched_param sp;
    int ret;

    if (g_key_running) {
        return 0;
    }

    ret = pthread_attr_init(&attr);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] attr_init: %d\n", TAG, ret);
        return -ret;
    }
    sp.sched_priority = CONFIG_AI_AGENT_KEYMGR_PRIORITY;
    (void)pthread_attr_setschedpolicy(&attr, SCHED_RR);
    (void)pthread_attr_setschedparam(&attr, &sp);
    (void)pthread_attr_setstacksize(&attr, CONFIG_AI_AGENT_KEYMGR_STACKSIZE);

    ret = pthread_create(&tid, &attr, key_manager_thread, NULL);
    (void)pthread_attr_destroy(&attr);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] pthread_create: %d\n", TAG, ret);
        return -ret;
    }

    pthread_detach(tid);
    g_key_running = true;
    syslog(LOG_INFO, "[%s] context-key thread started\n", TAG);
    return 0;
}

#endif /* CONFIG_AI_AGENT_KEYMGR */

