#!/usr/bin/env bash

set -euo pipefail
umask 077

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

usage() {
  cat >&2 <<EOF
usage: $0 (--workspace DIR --worktree DIR | --image FILE [--tools-dir DIR | --worktree DIR]) [options]

options:
  --jobs N             build parallelism (default: 12)
  --slot NAME          stable incremental build/package slot name
  --fresh              rebuild this worktree's bound build slot
  --placeholder        use bundled AP recovery placeholder
  --image FILE         flash an existing all-app.bin; skips build/package
  --tools-dir DIR      tools directory for --image (contains bk7258-flash.sh)
  --flash              flash the verified all-app.bin (destructive)
  --device PATH        serial device (default: /dev/ttyUSB0)
  --port N             bk_loader port number (default: 0)
EOF
  exit 2
}

WORKSPACE=""
WORKTREE=""
IMAGE=""
TOOLS_DIR=""
JOBS=12
SLOT=""
FRESH=0
OPENVELA_AP=1
FLASH=0
DEVICE=/dev/ttyUSB0
PORT=0
EXPECTED_LOADER_SHA256=55221d83d5582c362aab27d8883d799acf5eaa7b735d51135e01b0a24156b9ab

while [[ $# -gt 0 ]]; do
  case "$1" in
    --workspace) WORKSPACE="$2"; shift 2 ;;
    --worktree) WORKTREE="$2"; shift 2 ;;
    --image) IMAGE="$2"; shift 2 ;;
    --tools-dir) TOOLS_DIR="$2"; shift 2 ;;
    --jobs) JOBS="$2"; shift 2 ;;
    --slot) SLOT="$2"; shift 2 ;;
    --fresh) FRESH=1; shift ;;
    --placeholder) OPENVELA_AP=0; shift ;;
    --flash) FLASH=1; shift ;;
    --device) DEVICE="$2"; shift 2 ;;
    --port) PORT="$2"; shift 2 ;;
    -h|--help) usage ;;
    *) usage ;;
  esac
done

[[ "$JOBS" =~ ^[1-9][0-9]*$ ]] || usage

if [[ "$FLASH" -eq 1 ]]; then
  if [[ "$EUID" -eq 0 ]]; then

    device = child_serial_device(command)

    child, master = pty.fork()
    if child == 0:
        if sys.platform.startswith("linux"):
            import ctypes

            libc = ctypes.CDLL(None)
            libc.prctl(1, signal.SIGTERM)
        os.execvp(command[0], command)

    pending = b""
    reset_count = 0
    got_bus = False
    injected = False
    injected_at = 0.0
    retried = False
    manual_prompted = False
    received_signal: int | None = None

    def forward(signum: int, _frame: object) -> None:
        nonlocal received_signal
        received_signal = signum
        try:
            os.killpg(child, signum)
        except ProcessLookupError:
            pass

    previous = {
        sig: signal.signal(sig, forward)
        for sig in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP)
    }
    try:
        while True:
            readable, _, _ = select.select([master], [], [], 0.1)

            if master not in readable:
                now = time.monotonic()
                if injected and not got_bus:
                    if not retried and now - injected_at >= RETRY_AFTER:
                        retried = True
                        if inject_reboot_bootloader(device):
                            banner("[BK7258] 自动复位重试已发送")
                    elif not manual_prompted and now - injected_at >= MANUAL_AFTER:
                        manual_prompted = True
                        banner(
                            "[BK7258] 自动复位未生效（固件可能不含 bootloader 复位补丁）；"
                            "GetBus 期间请手动按复位键",
                            bell=True,
                        )
                finished, status = os.waitpid(child, os.WNOHANG)
                if finished:
                    return os.waitstatus_to_exitcode(status)
                continue

            try:
                chunk = os.read(master, 4096)
            except OSError:
                chunk = b""
            if not chunk:
                _, status = os.waitpid(child, 0)
                return os.waitstatus_to_exitcode(status)

            os.write(sys.stdout.fileno(), chunk)
            pending = (pending + chunk)[-8192:]

            if not injected and CONNECT_MARKER in pending:
                injected = True
                injected_at = time.monotonic()
                if inject_reboot_bootloader(device):
                    banner(
                        "[BK7258] downloader 就绪：已自动注入 reboot bootloader"
                        "（软件复位进下载模式，无需人工）"
                    )

            while SUCCESS_MARKER in pending:
                _, pending = pending.split(SUCCESS_MARKER, 1)
                got_bus = True
                banner("[BK7258] GetBus 握手成功（零人工），等待烧录完成")

            while RESET_MARKER in pending:
                _, pending = pending.split(RESET_MARKER, 1)
                reset_count += 1
                if manual_prompted:
                    banner(
