int bk7258_ap_reset_for_rptun(void)
{
  int ret;

  ret = nxmutex_lock(&g_ap_start_lock);
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_ap_force_reset();
  if (ret >= 0)
    {
      g_ap_started = false;
    }

  nxmutex_unlock(&g_ap_start_lock);
  return ret;
}

