243	   * default placeholder/recovery package safe if a prior stage left CPU1
244	   * running: CPU1 is parked before OVAP identity or vector validation. */
245	
246	  ret = bk7258_ap_force_reset();
247	  if (ret < 0)
248	    {
249	      syslog(LOG_ERR, "[AP] start: force_reset failed ret=%d\n", ret);
250	      goto out_unlock;
251	    }
252	
253	  image_contract =
254	    (const volatile struct bk7258_ap_image_contract_s *)
255	      (BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_IMAGE_CONTRACT_OFFSET);
256	  syslog(LOG_INFO,
257	         "[AP] start: contract@%p magic=%08lx abi=%lu build=%08lx "
258	         "vbase=%08lx (want magic=%08lx vbase=%08lx)\n",
259	         (const void *)image_contract,
260	         (unsigned long)image_contract->magic,
261	         (unsigned long)image_contract->abi_version,
262	         (unsigned long)image_contract->build_id,
263	         (unsigned long)image_contract->vector_base,
264	         (unsigned long)BK7258_AP_IMAGE_MAGIC,
265	         (unsigned long)BK7258_AP_XIP_VECTOR_BASE);
266	  if (image_contract->magic != BK7258_AP_IMAGE_MAGIC ||
267	      image_contract->abi_version != BK7258_AP_BOOT_ABI_VERSION ||
268	      image_contract->build_id != BK7258_AP_BUILD_ID ||
269	      image_contract->vector_base != BK7258_AP_XIP_VECTOR_BASE)
270	    {
271	      syslog(LOG_ERR, "[AP] start: contract mismatch -> ENOEXEC\n");
272	      ret = -ENOEXEC;
273	      goto out_unlock;
274	    }
275	
276	  initial_msp = bk7258_ap_reg_read(BK7258_AP_XIP_VECTOR_BASE);
277	  reset_pc = bk7258_ap_reg_read(BK7258_AP_XIP_VECTOR_BASE + sizeof(uint32_t));
278	  syslog(LOG_INFO,
279	         "[AP] start: vbase=%08lx msp=%08lx reset_pc=%08lx "
280	         "(ram=[%08lx..%08lx] xip_end=%08lx)\n",
281	         (unsigned long)BK7258_AP_XIP_VECTOR_BASE,
282	         (unsigned long)initial_msp, (unsigned long)reset_pc,
283	         (unsigned long)BK7258_AP_RAM_BASE, (unsigned long)BK7258_AP_RAM_END,
284	         (unsigned long)(BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_XIP_SIZE));
285	  if (initial_msp <= BK7258_AP_RAM_BASE ||
286	      initial_msp > BK7258_AP_RAM_END ||
287	      (initial_msp & 7) != 0 ||
288	      (reset_pc & 1) == 0 ||
289	      (reset_pc & ~UINT32_C(1)) < BK7258_AP_XIP_VECTOR_BASE ||
290	      (reset_pc & ~UINT32_C(1)) >=
291	        BK7258_AP_XIP_VECTOR_BASE + BK7258_AP_XIP_SIZE)
292	    {
293	      syslog(LOG_ERR, "[AP] start: vector bounds check failed -> ENOEXEC\n");
294	      ret = -ENOEXEC;
295	      goto out_unlock;
296	    }
297	
298	  /* Power the CPU1 domain up through the authority sequence before releasing
299	   * the core, the way upstream does it (startup_cpu1.c:261 votes
300	   * PM_POWER_MODULE_NAME_CPU1 ON ahead of the release).
301	   *
302	   * This step was missing, and it only started to matter once
303	   * sys_hal_low_power_hardware_init() moved to __start() (bk7258_start.c) to
304	   * match the authority's boot position.  That function powers CPU1 and CPU2
305	   * OFF -- upstream a no-op, because neither core has been started yet -- so
306	   * the AP release below now runs against a halted, powered-down core.  Board
307	   * evidence (/tmp/0910-vela-11.log):
308	   *
309	   *   [AP] start: cpu1_ctrl before=0000001a          POWER_DOWN|HALT|bit4
310	   *   [AP] start: cpu1_ctrl readback=00000038 expected=00000020 -> EIO
311	   *   [AP] CPU1 release failed: -1 errno=5
312	   *
313	   * POWER_DOWN (bit1) does clear and stay clear; HALT (bit3) and bit4 read
314	   * back set.  That is a settling problem rather than a missing write: the
315	   * authority clears power and halt in two separate register writes and then
316	   * spins 1000 iterations, with the comment "wait halt really cleared, clock
317	   * support finish" (sys_hal.c:150-157), whereas the sequence below clears both
318	   * in one write and reads back after a barrier.  Our own settling loop
319	   * (BK7258_AP_POWER_STABILIZE_LOOPS) sits AFTER that read-back check, so the
320	   * check lands inside the window the hardware needs.
321	   *
322	   * Same register on both sides -- ours is BK7258_SYS_BASE + 0x014, the
323	   * authority's sys_cpu1_int_halt_clk_op is SOC_SYS_REG_BASE + (0x5 << 2)
324	   * (sys_ll.h:292); both resolve to 0x44010014.
325	   *
326	   * Called before up_irq_save() on purpose: the authority sequence contains a
327	   * busy-wait, and there is no reason to hold interrupts off across it.
328	   * Nothing else in this image touches the CPU1 power domain, so the state
329	   * cannot change between here and the release below.
330	   *
331	   * sys_hal_module_power_ctrl() rather than bk_pm_module_vote_power_ctrl() for
332	   * the same reason as the PSRAM domain in bk7258_psram.c: the vote function in
333	   * this port (hal_port/platform_shim.c:188) has no CPU1 branch and would answer
334	   * BK_ERR_NOT_SUPPORT, and it is built only under CONFIG_BK7258_WIFI.  The HAL
335	   * entry is authority code under pm/ and compiles unconditionally.  When
336	   * platform_shim's vote layer is replaced by the authority's pm.c this becomes
337	   * the CPU1 vote and this call site is the only line that changes.
338	   *
339	   * Declared locally to keep the PM module's SoC headers out of board code. */
340	
341	  {
342	    extern void sys_hal_module_power_ctrl(int module, int power_state);
343	
344	    /* POWER_MODULE_NAME_CPU1 == 17, CPU2 == 19, POWER_MODULE_STATE_ON == 0
345	     * (aon_pmu/.../sys_types.h:337,339 and :417). */
346	
347	    sys_hal_module_power_ctrl(17 /* CPU1 */, 0 /* STATE_ON */);
348	
349	    /* CPU2 too, because sys_hal_power_config_default() switched off both slave
350	     * cores and the authority restores both before starting either
351	     * (cli_main.c:509-516 votes CPU1 ON, start_cpu1_core(), CPU2 ON,
352	     * start_cpu2_core()).
353	     *
354	     * Done from here rather than next to the CPU2 release in
355	     * chips/bk7258/bk7258_smp.c because that file belongs to the AP image,
356	     * which does not link sys_hal_module_power_ctrl at all -- the PM module is
357	     * CP-only (verified with nm: ap/nuttx has up_cpu_start and
358	     * bk7258_smp_initialize, cp/nuttx has sys_hal_module_power_ctrl).  CP is
359	     * also the core that switched the domain off, so restoring it here keeps
360	     * the whole slave-core power lifecycle on one side.
361	     *
362	     * Not what fixed the CPU2 release: the fault record showed bit1 POWER_DOWN
363	     * already clear (fault=0x43325438, low byte 0x38 = HALT|speed|RXEVT_SEL),
364	     * so bk7258_smp.c's own direct write was landing.  This is authority
365	     * symmetry, not the repair -- dropping HALT from
366	     * BK7258_CPU2_CTRL_LIFECYCLE_MASK is. */
367	
368	    sys_hal_module_power_ctrl(19 /* CPU2 */, 0 /* STATE_ON */);
369	  }
370	
371	  flags = up_irq_save();
372	
373	  /* Follow Armino's BK7258 lifecycle order. CPU_CURRENT_RUN_STATUS is
374	   * diagnostic only; its transient values are not a launch precondition. */
375	
376	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
377	  syslog(LOG_INFO, "[AP] start: cpu1_ctrl before=%08lx\n",
378	         (unsigned long)control);
379	  control &= ~(BK7258_SYS_CPU1_RESET_RELEASE |
380	               BK7258_SYS_CPU1_POWER_DOWN |
381	               BK7258_SYS_CPU1_HALT |
382	               BK7258_SYS_CPU1_OFFSET_MASK);
383	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
384	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
385	  bk7258_ap_lifecycle_barrier();
386	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
387	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
388	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
389	    {
390	      syslog(LOG_ERR,
391	             "[AP] start: cpu1_ctrl readback=%08lx expected=%08lx -> EIO\n",
392	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
393	             (unsigned long)expected);
394	      up_irq_restore(flags);
395	      ret = -EIO;
396	      goto out_unlock;
397	    }
398	
399	  /* Keep the vendor power-domain settling window explicit and
400	   * non-optimizable. */
401	
402	  for (count = 0; count < BK7258_AP_POWER_STABILIZE_LOOPS; count++)
403	    {
404	      __asm__ volatile ("nop");
405	    }
406	
407	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
408	    {
409	      /* HALTED_STATE dropped from the wait condition for the same reason it is
410	       * out of BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK: the authority releases CPU1
411	       * from a state where halt is asserted and never waits for it to clear
412	       * (reset_cpu1_core(), system_main.c:175-183).  Keeping it here would only
413	       * move the failure from the -EIO above to the -ETIMEDOUT below.
414	       *
415	       * PWR_DW_STATE and RESET_STATE stay: pwr_dw is what the CPU1 power vote
416	       * ahead of this loop actually clears, and it was observed clearing on the
417	       * board, so both remain meaningful preconditions. */
418	
419	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
420	      if ((status & (BK7258_SYS_CPU1_PWR_DW_STATE |
421	                     BK7258_SYS_CPU1_RESET_STATE)) == 0)
422	        {
423	          break;
424	        }
425	    }
426	
427	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
428	    {
429	      syslog(LOG_ERR,
430	             "[AP] start: power-wait timeout cpu_status=%08lx -> ETIMEDOUT\n",
431	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
432	      up_irq_restore(flags);
433	      ret = -ETIMEDOUT;
434	      goto out_unlock;
435	    }
436	
437	  syslog(LOG_INFO, "[AP] start: cpu1 powered up, cpu_status=%08lx after %u\n",
438	         (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS),
439	         (unsigned int)count);
440	
441	  /* CPU1 is still held in reset and CP interrupts remain disabled, so this
442	   * is the exclusive ownership window for the shared audio power/SRAM RMWs.
443	   * A failed readback keeps AP in reset and prevents an unusable audio
444	   * subsystem from being published.
445	   */
446	
447	  audio_wake_attempted = true;
448	  audio_wake_ret = bk7258_ap_audio_wake(&audio_wake);
449	  if (audio_wake_ret < 0)
450	    {
451	      up_irq_restore(flags);
452	      ret = audio_wake_ret;
453	      goto out_unlock;
454	    }
455	
456	  /* CPU1 is now held in reset, so CP owns SWAP exclusively while it creates
457	   * the next boot sequence. This ordering also makes a future AP restart safe:
458	   * the old AP cannot race the new CP record with a final heartbeat write. */
459	
460	  boot_sequence = bk7258_ap_record_prepare();
461	
462	  control = bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL);
463	  control &= ~(BK7258_SYS_CPU1_OFFSET_MASK |
464	               BK7258_SYS_CPU1_RESET_RELEASE);
465	  /* The Armino setter takes address >> 8 as a bitfield value. This direct
466	   * register write must place that value back into bits [31:8]. */
467	
468	  control |= BK7258_SYS_CPU_BOOT_OFFSET(BK7258_AP_XIP_VECTOR_BASE);
469	  control |= BK7258_SYS_CPU1_RXEVT_SEL;
470	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL, control);
471	  bk7258_ap_lifecycle_barrier();
472	  expected = control & BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
473	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
474	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
475	    {
476	      syslog(LOG_ERR,
477	             "[AP] start: vec-offset readback=%08lx expected=%08lx -> EIO\n",
478	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
479	             (unsigned long)expected);
480	      up_irq_restore(flags);
481	      ret = -EIO;
482	      goto out_unlock;
483	    }
484	
485	  syslog(LOG_INFO, "[AP] start: releasing CPU1 reset (seq=%u)\n",
486	         (unsigned int)boot_sequence);
487	  bk7258_ap_reg_write(BK7258_SYS_CPU1_CTRL,
488	                      control | BK7258_SYS_CPU1_RESET_RELEASE);
489	  released = true;
490	  bk7258_ap_lifecycle_barrier();
491	  expected = (control | BK7258_SYS_CPU1_RESET_RELEASE) &
492	             BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK;
493	  if ((bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL) &
494	       BK7258_AP_CPU1_CTRL_LIFECYCLE_MASK) != expected)
495	    {
496	      syslog(LOG_ERR,
497	             "[AP] start: release readback=%08lx expected=%08lx -> EIO\n",
498	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU1_CTRL),
499	             (unsigned long)expected);
500	      up_irq_restore(flags);
501	      ret = -EIO;
502	      goto out_rollback;
503	    }
504	
505	  for (count = 0; count < BK7258_AP_POWER_WAIT_LOOPS; count++)
506	    {
507	      status = bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS);
508	      if ((status & BK7258_SYS_CPU1_RESET_STATE) != 0)
509	        {
510	          break;
511	        }
512	    }
513	
514	  if (count == BK7258_AP_POWER_WAIT_LOOPS)
515	    {
516	      syslog(LOG_ERR,
517	             "[AP] start: post-release reset-state timeout "
518	             "cpu_status=%08lx -> ETIMEDOUT\n",
519	             (unsigned long)bk7258_ap_reg_read(BK7258_SYS_CPU_STATUS));
520	      up_irq_restore(flags);
521	      ret = -ETIMEDOUT;
522	      goto out_rollback;
523	    }
524	
525	  up_irq_restore(flags);
526	
527	  /* Do not report a successful start merely because MMIO writes completed.
528	   * The current-sequence RESET_ENTERED record proves CPU1 fetched the AP
529	   * vector and executed team OpenVela startup code. */
530	
531	  for (count = 0; count < BK7258_AP_RESET_WAIT_ATTEMPTS; count++)
532	    {
533	      if (bk7258_ap_record_read(&record) &&
534	          record.boot_sequence == boot_sequence)
535	        {
536	          if (record.stage == BK7258_AP_STAGE_RESET_ENTERED ||
537	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
538	            {
539	              g_ap_boot_sequence = boot_sequence;
540	              g_ap_started = true;
541	              syslog(LOG_INFO,
542	                     "[AP] start: OK stage=%s seq=%u after %u\n",
543	                     bk7258_ap_stage_name(record.stage),
544	                     (unsigned int)boot_sequence,
545	                     (unsigned int)count);
546	              ret = 0;
547	              goto out_unlock;
548	            }
549	
550	          if (record.stage == BK7258_AP_STAGE_FAULT)
551	            {
552	              syslog(LOG_ERR,
553	                     "[AP] start fault seq=%u code=0x%08x\n",
554	                     (unsigned int)boot_sequence,
555	                     (unsigned int)record.fault);
556	              ret = -EFAULT;
557	              goto out_rollback;
558	            }
559	        }
560	
561	      nxsig_usleep(BK7258_AP_RESET_WAIT_USEC);
562	    }
563	
564	  syslog(LOG_ERR,
565	         "[AP] start: boot-record wait timeout seq=%u attempts=%u "
566	         "(last valid=%d seq=%u stage=%u) -> ETIMEDOUT\n",
567	         (unsigned int)boot_sequence,
568	         (unsigned int)BK7258_AP_RESET_WAIT_ATTEMPTS,
569	         (int)bk7258_ap_record_read(&record),
570	         (unsigned int)record.boot_sequence,
571	         (unsigned int)record.stage);
572	  ret = -ETIMEDOUT;
573	
574	out_rollback:
575	  if (released)
576	    {
577	      int reset_ret = bk7258_ap_force_reset();
578	      if (reset_ret < 0)
579	        {
580	          syslog(LOG_ERR, "[AP] rollback reset failed: %d\n", reset_ret);
581	        }
582	    }
583	
584	out_unlock:
585	  if (audio_wake_attempted)
586	    {
587	      syslog(audio_wake_ret < 0 ? LOG_ERR : LOG_INFO,
588	             "[AP] audio wake ret=%d pwr=%08lx->%08lx "
589	             "sd=%08lx->%08lx ds=%08lx->%08lx\n",
590	             audio_wake_ret,
591	             (unsigned long)audio_wake.power_before,
592	             (unsigned long)audio_wake.power_after,
593	             (unsigned long)audio_wake.mem_ctrl1_before,
594	             (unsigned long)audio_wake.mem_ctrl1_after,
595	             (unsigned long)audio_wake.mem_ctrl2_before,
596	             (unsigned long)audio_wake.mem_ctrl2_after);
597	    }
598	
599	  nxmutex_unlock(&g_ap_start_lock);
600	  return ret;
601	}
602	
603	static int bk7258_ap_recover_transport(void)
604	{
605	  unsigned int attempt;
606	  int ret;
607	
608	  if (g_ap_recovering)
609	    {
610	      return -EALREADY;
611	    }
612	
613	  g_ap_recovering = true;
614	  g_ap_started = false;
615	
616	  /* The generic RPTUN stop path destroys the remoteproc VirtIO device and
617	   * broadcasts RPMsg device-destroy callbacks before returning the transport
618	   * to OFFLINE.  Do this before board_start_cpu() resets AP again, otherwise
619	   * the old vrings and uart_rpmsg endpoint can survive into the new AP
620	   * generation. */
621	
622	  /* remoteproc_stop() rejects CONFIGURED/READY while the RPTUN worker is
623	   * still completing its start transaction.  AP can reboot exactly during
624	   * that window, so treat -EBUSY as a transient state and retry in this
625	   * task context.  Do not call rptun_initialize() here: the /dev/rptun/ap
626	   * instance is already registered and initialization is one-shot. */
627	
628	  ret = -EBUSY;
629	  for (attempt = 0; attempt < BK7258_AP_RPTUN_STOP_ATTEMPTS; attempt++)
630	    {
631	      ret = rptun_poweroff("ap");
632	      if (ret != -EBUSY)
633	        {
634	          break;
635	        }
636	
637	      nxsig_usleep(BK7258_AP_RPTUN_STOP_WAIT_USEC);
638	    }
639	
640	  if (ret == -EBUSY)
641	    {
642	      syslog(LOG_ERR,
643	             "[AP] RPTUN teardown remained busy after %u attempts\n",
644	             BK7258_AP_RPTUN_STOP_ATTEMPTS);
645	    }
646	
647	  if (ret < 0 && ret != -ENODEV)
648	    {
649	      syslog(LOG_ERR, "[AP] RPTUN teardown failed: %d\n", ret);
650	      goto out;
651	    }
652	
653	  ret = rptun_boot("ap");
654	  if (ret < 0)
655	    {
656	      syslog(LOG_ERR, "[AP] RPTUN restart failed: %d\n", ret);
657	    }
658	
659	out:
660	  g_ap_recovering = false;
661	  return ret;
662	}
663	
664	static int bk7258_ap_monitor(int argc, char *argv[])
665	{
666	  struct bk7258_ap_boot_record_s record;
667	  uint32_t last_heartbeat = 0;
668	  uint32_t last_stage = UINT32_MAX;
669	  uint32_t last_dbg = 0;
670	  unsigned int invalid_samples = 0;
671	  unsigned int stagnant_samples = 0;
672	  bool invalid_reported = false;
673	  bool stalled_reported = false;
674	  bool heartbeat_seen = false;
675	
676	  (void)argc;
677	  (void)argv;
678	
679	  for (; ; )
680	    {
681	      if (!bk7258_ap_record_read(&record) ||
682	          (record.boot_sequence != g_ap_boot_sequence &&
683	           !g_ap_recovering))
684	        {
685	          if (bk7258_ap_record_read(&record) &&
686	              record.boot_sequence != g_ap_boot_sequence &&
687	              record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
688	            {
689	              syslog(LOG_INFO,
690	                     "[AP] peer generation changed old=%u new=%u; rebuilding RPTUN\n",
691	                     (unsigned int)g_ap_boot_sequence,
692	                     (unsigned int)record.boot_sequence);
693	              (void)bk7258_ap_recover_transport();
694	              nxsig_usleep(1000 * 1000);
695	              continue;
696	            }
697	
698	          invalid_samples++;
699	          stagnant_samples = 0;
700	          if (invalid_samples >= BK7258_AP_STALL_SAMPLES && !invalid_reported)
701	            {
702	              syslog(LOG_ERR,
703	                     "[AP] no valid record for seq=%u\n",
704	                     (unsigned int)g_ap_boot_sequence);
705	              invalid_reported = true;
706	            }
707	
708	          nxsig_usleep(1000 * 1000);
709	          continue;
710	        }
711	
712	      invalid_samples = 0;
713	      invalid_reported = false;
714	
715	      {
716	        uint32_t dbg = bk7258_ap_dbg_read();
717	
718	        if (dbg != last_dbg)
719	          {
720	            syslog(LOG_INFO, "[AP] bootmark=0x%08x\n", dbg);
721	            last_dbg = dbg;
722	          }
723	      }
724	
725	      if (record.stage != last_stage)
726	        {
727	          if (record.stage == BK7258_AP_STAGE_FAULT &&
728	              (record.fault & UINT32_C(0xffff0000)) ==
729	              (BK7258_AP_FAULT_PANIC_BASE & UINT32_C(0xffff0000)))
730	            {
731	              /* The AP panic notifier encodes the assertion location:
732	               * high byte = a short hash of the filename, low byte = line
733	               * number. */
734	
735	              syslog(LOG_ERR,
736	                     "[AP] stage=fault seq=%u panic filehash=0x%02x line=%u\n",
737	                     (unsigned int)record.boot_sequence,
738	                     (unsigned int)((record.fault >> 8) & UINT32_C(0xff)),
739	                     (unsigned int)(record.fault & UINT32_C(0xff)));
740	            }
741	          else
742	            {
743	              syslog(record.stage == BK7258_AP_STAGE_FAULT ? LOG_ERR : LOG_INFO,
744	                     "[AP] stage=%s seq=%u fault=0x%08x\n",
745	                     bk7258_ap_stage_name(record.stage),
746	                     (unsigned int)record.boot_sequence,
747	                     (unsigned int)record.fault);
748	            }
749	
750	          last_stage = record.stage;
751	        }
752	
753	      if (record.stage == BK7258_AP_STAGE_SCHEDULER_RUNNING)
754	        {
755	          if (record.heartbeat != last_heartbeat)
756	            {
757	              stagnant_samples = 0;
758	              stalled_reported = false;
759	              last_heartbeat = record.heartbeat;
760	              heartbeat_seen = true;
761	            }
762	          else if (heartbeat_seen)
763	            {
