   267	            btn_buttonset_t bit = key_bit(i);
   268	            if ((change & bit) == 0) {
   269	                continue;
   270	            }
   271	            if (cur & bit) {
   272	                g_held[i] = true;
   273	                g_press_ms[i] = key_now_ms();
   274	            } else {
   275	                if (!g_held[i]) {
   276	                    continue;
   277	                }
   278	                g_held[i] = false;
