   374	int lvgl_ui_channel_set_approval(const char *tool, const char *hint)
   375	{
   376	  struct ui_rpmsg_msg m;
   377	  size_t off = 0, tlen, hlen;
   378	  int ret;
   379	
   380	  /* Guard against NULL — memcpy(dst, NULL, 0) is UB even at zero length. */
   381	  const char *st = tool != NULL ? tool : "";
   382	  const char *sh = hint != NULL ? hint : "";
   383	
   384	  memset(&m, 0, sizeof(m));
   385	  m.op = UI_RPMSG_SET_APPROVAL;
   386	
   387	  tlen = strlen(st);
   388	  hlen = strlen(sh);
   389	  if (tlen + hlen + 2 > UI_RPMSG_MAX_PAYLOAD)
   390	    {
   391	      /* Truncate hint first, then tool, keeping both NUL-terminated. */
   392	      size_t room = UI_RPMSG_MAX_PAYLOAD - 2;   /* 2 NULs */
   393	      if (tlen > room)
   394	        {
   395	          tlen = room;
   396	          hlen = 0;
   397	        }
   398	      else if (tlen + hlen > room)
   399	        {
   400	          hlen = room - tlen;
   401	        }
   402	    }
   403	
   404	  memcpy(m.payload + off, st, tlen); off += tlen;
   405	  m.payload[off++] = '\0';
   406	  memcpy(m.payload + off, sh, hlen); off += hlen;
   407	  m.payload[off++] = '\0';
   408	  m.payload_len = (uint16_t)off;
   409	
   410	  ret = ui_rpmsg_send(&m);
