137	#if KEYMGR_HAVE_UI
138	    /* No approval: scroll the chat transcript. S2 up (older), S3 down (newer). */
139	    int dir = (idx == KEYMGR_IDX_S2) ? 0 : 1;
140	    (void)lvgl_ui_channel_scroll(dir);
141	    syslog(LOG_INFO, "[%s] S%d short → scroll %s\n", TAG, idx,
142	           dir == 0 ? "up" : "down");
143	#else
144	    syslog(LOG_INFO, "[%s] S%d short (no UI channel)\n", TAG, idx);
145	#endif
146	}
