148	/* ── long press: model / session ───────────────────────────────────── */
149	
150	static void key_long_press(int idx)
151	{
152	    if (idx == KEYMGR_IDX_S2) {
153	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
154	        /* Cycle to the next model the bridge offers.  The list is display-only
155	         * authority: the bridge still validates the name, so a stale entry is
156	         * refused rather than silently misapplied. */
157	        static struct remote_model_view_s mv;
158	        if (remote_ctrl_channel_model_view(&mv) == OK && mv.count > 0) {
159	            int cur = -1;
160	            int i;
161	            for (i = 0; i < mv.count; i++) {
162	                if (strcmp(mv.options[i], mv.current) == 0) {
163	                    cur = i;
164	                    break;
165	                }
166	            }
167	            int next = (cur + 1) % mv.count;
168	            (void)remote_ctrl_channel_select_model(mv.options[next]);
169	#if KEYMGR_HAVE_UI
170	            char body[REMOTE_MODEL_MAX + 16];
171	            snprintf(body, sizeof(body), "model: %s", mv.options[next]);
172	            lvgl_toast_show_async("Model", body, 0x4caf50, 2500);
173	#endif
174	            syslog(LOG_INFO, "[%s] S2 long → model %s\n", TAG, mv.options[next]);
175	        } else {
176	            syslog(LOG_WARNING, "[%s] S2 long → no model list\n", TAG);
177	        }
178	#else
179	        syslog(LOG_INFO, "[%s] S2 long (remote ctrl off)\n", TAG);
180	#endif
181	    } else {
182	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
183	        (void)remote_ctrl_channel_new_session();
184	#if KEYMGR_HAVE_UI
185	        lvgl_toast_show_async("Session", "new session", 0x4caf50, 2500);
186	#endif
187	        syslog(LOG_INFO, "[%s] S3 long → new session\n", TAG);
188	#else
189	        syslog(LOG_INFO, "[%s] S3 long (remote ctrl off)\n", TAG);
190	#endif
191	    }
192	}
193	
194	/* ── watch thread ──────────────────────────────────────────────────── */
195	
196	static void* key_manager_thread(void* arg)
197	{
198	    const char* devpath = CONFIG_AI_AGENT_KEYMGR_DEVPATH;
199	    btn_buttonset_t mask = key_bit(KEYMGR_IDX_S2) | key_bit(KEYMGR_IDX_S3);
200	    struct btn_pollevents_s pe;
201	    struct pollfd pfd;
202	    btn_buttonset_t supported;
203	    btn_buttonset_t last;
204	    bool have_baseline = false;
205	    int fd;
206	    int i;
207	
208	    (void)arg;
209	
210	    fd = open(devpath, O_RDONLY);
211	    if (fd < 0) {
212	        syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
213	        return NULL;
214	    }
215	
216	    supported = 0;
217	    if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0) {
218	        syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
219	        close(fd);
220	        return NULL;
221	    }
222	    if ((supported & mask) != mask) {
223	        syslog(LOG_ERR, "[%s] S2/S3 not all in supported set 0x%08lx\n",
224	               TAG, (unsigned long)supported);
225	        close(fd);
226	        return NULL;
227	    }
228	
229	    pe.bp_press   = mask;
230	    pe.bp_release = mask;
231	    (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
232	
233	    pfd.fd     = fd;
234	    pfd.events = POLLIN;
235	    last       = 0;
236	
237	    syslog(LOG_INFO, "[%s] watching %s S2/S3 (context keys)\n", TAG, devpath);
238	
239	    for (;;) {
240	        btn_buttonset_t cur;
241	        btn_buttonset_t change;
242	        ssize_t nread;
243	
244	        if (poll(&pfd, 1, -1) < 0) {
245	            if (errno == EINTR) {
246	                continue;
247	            }
248	            syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
249	            break;
250	        }
251	        if ((pfd.revents & POLLIN) == 0) {
252	            continue;
253	        }
254	
255	        nread = read(fd, &cur, sizeof(cur));
256	        if (nread != (ssize_t)sizeof(cur)) {
257	            continue;
258	        }
259	        if (!have_baseline) {
260	            last = cur;
261	            have_baseline = true;
262	            continue;
263	        }
264	
265	        change = cur ^ last;
266	        for (i = KEYMGR_IDX_S2; i <= KEYMGR_IDX_S3; i++) {
267	            btn_buttonset_t bit = key_bit(i);
268	            if ((change & bit) == 0) {
269	                continue;
270	            }
271	            if (cur & bit) {
272	                g_held[i] = true;
273	                g_press_ms[i] = key_now_ms();
274	            } else {
275	                if (!g_held[i]) {
276	                    continue;
277	                }
278	                g_held[i] = false;
279	                uint64_t dur = key_now_ms() - g_press_ms[i];
280	                if (dur >= CONFIG_AI_AGENT_KEYMGR_LONG_MS) {
281	                    key_long_press(i);
282	                } else {
283	                    key_short_press(i);
284	                }
285	            }
286	        }
287	        last = cur;
288	    }
289	
290	    close(fd);
291	    return NULL;
292	}
293	
294	int key_manager_start(void)
295	{
296	    pthread_t tid;
297	    pthread_attr_t attr;
298	    struct sched_param sp;
299	    int ret;
300	
301	    if (g_key_running) {
302	        return 0;
303	    }
304	
305	    ret = pthread_attr_init(&attr);
306	    if (ret != 0) {
307	        syslog(LOG_ERR, "[%s] attr_init: %d\n", TAG, ret);
308	        return -ret;
309	    }
310	    sp.sched_priority = CONFIG_AI_AGENT_KEYMGR_PRIORITY;
311	    (void)pthread_attr_setschedpolicy(&attr, SCHED_RR);
312	    (void)pthread_attr_setschedparam(&attr, &sp);
313	    (void)pthread_attr_setstacksize(&attr, CONFIG_AI_AGENT_KEYMGR_STACKSIZE);
314	
315	    ret = pthread_create(&tid, &attr, key_manager_thread, NULL);
316	    (void)pthread_attr_destroy(&attr);
317	    if (ret != 0) {
318	        syslog(LOG_ERR, "[%s] pthread_create: %d\n", TAG, ret);
319	        return -ret;
320	    }
321	
322	    pthread_detach(tid);
323	    g_key_running = true;
324	    syslog(LOG_INFO, "[%s] context-key thread started\n", TAG);
325	    return 0;
326	}
327	
328	#endif /* CONFIG_AI_AGENT_KEYMGR */
