46	#  define CONFIG_TESTING_BK7258_BTN_DEVPATH "/dev/btn0"
47	#endif
48	
49	#ifndef CONFIG_TESTING_BK7258_BTN_LONG_MS
50	#  define CONFIG_TESTING_BK7258_BTN_LONG_MS 800
51	#endif
52	
53	#define BTN_MAX_BITS 32
54	
55	/****************************************************************************
56	 * Private Data
57	 ****************************************************************************/
58	
59	/* Long-press threshold, in ms.  Overridable with -t <ms> at runtime. */
60	
61	static int g_long_ms = CONFIG_TESTING_BK7258_BTN_LONG_MS;
62	
63	/****************************************************************************
64	 * Private Functions
65	 ****************************************************************************/
66	
67	/* Monotonic-ish millisecond timestamp.  CLOCK_MONOTONIC is not enabled on
68	 * this board, so CLOCK_REALTIME is used; only differences matter here and
69	 * the epoch never changes at runtime, so it is safe for this purpose.
70	 */
71	
72	static int64_t now_ms(void)
73	{
74	  struct timespec ts;
75	
76	  clock_gettime(CLOCK_REALTIME, &ts);
77	  return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
78	}
79	
80	static const char *btn_name(unsigned int idx)
81	{
82	  switch (idx)
83	    {
84	      case 0:
85	        return "KEY1";
86	      case 1:
87	        return "KEY2";
88	      case 2:
89	        return "KEY3";
90	      default:
91	        return "KEY?";
92	    }
93	}
94	
95	/* Dispatch hooks.  These are the only two places the business application
96	 * needs to wire into; today they just print.  A "trigger-on-hold" policy
97	 * (act as soon as the threshold is crossed, while still held) would instead
98	 * replace the blocking poll() with a timed poll() to the next threshold.
99	 */
100	
101	static void on_short_press(unsigned int idx, int64_t dur_ms)
102	{
103	  printf("btn0: %s short press (%lld ms)\n",
104	         btn_name(idx), (long long)dur_ms);
105	}
106	
107	static void on_long_press(unsigned int idx, int64_t dur_ms)
108	{
109	  printf("btn0: %s long press (%lld ms)\n",
110	         btn_name(idx), (long long)dur_ms);
111	}
112	
113	static void usage(FAR const char *prog)
114	{
115	  printf("Usage: %s [-t <long_ms>]\n", prog);
116	  printf("  -t <ms>  long-press threshold (default %d ms)\n",
117	         CONFIG_TESTING_BK7258_BTN_LONG_MS);
118	}
