120	/****************************************************************************
121	 * Public Functions
122	 ****************************************************************************/
123	
124	int main(int argc, FAR char *argv[])
125	{
126	  FAR const char *devpath = CONFIG_TESTING_BK7258_BTN_DEVPATH;
127	  struct btn_pollevents_s pe;
128	  struct pollfd pfd;
129	  btn_buttonset_t supported;
130	  btn_buttonset_t last;
131	  bool have_baseline;
132	  int64_t press_ms[BTN_MAX_BITS];
133	  bool pressed[BTN_MAX_BITS];
134	  unsigned int i;
135	  int fd;
136	  int option;
137	
138	  /* Parse options. */
139	
140	  while ((option = getopt(argc, argv, "t:h")) != ERROR)
141	    {
142	      switch (option)
143	        {
144	          case 't':
145	            g_long_ms = atoi(optarg);
146	            if (g_long_ms <= 0)
147	              {
148	                g_long_ms = CONFIG_TESTING_BK7258_BTN_LONG_MS;
149	              }
150	            break;
151	
152	          case 'h':
153	          default:
154	            usage(argv[0]);
155	            return 0;
156	        }
157	    }
158	
159	  fd = open(devpath, O_RDONLY);
160	  if (fd < 0)
161	    {
162	      printf("btn0: open %s failed: %d\n", devpath, errno);
163	      return 1;
164	    }
165	
166	  supported = 0;
167	  if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0)
168	    {
169	      printf("btn0: BTNIOC_SUPPORTED failed: %d\n", errno);
170	      close(fd);
171	      return 1;
172	    }
173	
174	  if (supported == 0)
175	    {
176	      printf("btn0: no buttons supported\n");
177	      close(fd);
178	      return 1;
179	    }
180	
181	  /* Ask to wake on both press and release edges (already the default). */
182	
183	  pe.bp_press   = supported;
184	  pe.bp_release = supported;
185	  (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
186	
187	  printf("btn0: watching buttons 0x%08lx, long-press threshold %d ms\n",
188	         (unsigned long)supported, g_long_ms);
189	  printf("btn0: press/release KEY1..KEY3 to see short/long classification\n");
190	
191	  pfd.fd     = fd;
192	  pfd.events = POLLIN;
193	
194	  memset(pressed, 0, sizeof(pressed));
195	  have_baseline = false;
196	  last = 0;
197	
198	  while (true)
199	    {
200	      btn_buttonset_t cur;
201	      btn_buttonset_t change;
202	      btn_buttonset_t press;
203	      btn_buttonset_t release;
204	      ssize_t nread;
205	      int64_t now;
206	
207	      if (poll(&pfd, 1, -1) < 0)
208	        {
209	          if (errno == EINTR)
210	            {
211	              continue;
212	            }
213	
214	          printf("btn0: poll failed: %d\n", errno);
215	          break;
216	        }
217	
218	      if ((pfd.revents & POLLIN) == 0)
219	        {
220	          continue;
221	        }
222	
223	      nread = read(fd, &cur, sizeof(cur));
224	      if (nread != (ssize_t)sizeof(cur))
225	        {
226	          continue;
227	        }
228	
229	      /* First read only establishes the baseline state. */
230	
231	      if (!have_baseline)
232	        {
233	          last = cur;
234	          have_baseline = true;
235	          continue;
236	        }
237	
238	      /* Compute press/release edges against our own last sample.  bit=1
239	       * means "pressed" (the buttons are active-low with pull-ups).
240	       */
241	
242	      change  = cur ^ last;
243	      press   = change & cur;
244	      release = change & ~cur;
245	      last    = cur;
246	
247	      now = now_ms();
248	      for (i = 0; i < BTN_MAX_BITS; i++)
249	        {
250	          btn_buttonset_t bit = (btn_buttonset_t)1 << i;
251	
252	          if ((press & bit) != 0)
253	            {
254	              pressed[i]  = true;
255	              press_ms[i] = now;
256	              printf("btn0: %s pressed\n", btn_name(i));
257	            }
258	          else if ((release & bit) != 0)
259	            {
260	              int64_t dur = now - press_ms[i];
261	
262	              pressed[i] = false;
263	              if (dur >= g_long_ms)
264	                {
265	                  on_long_press(i, dur);
266	                }
267	              else
268	                {
269	                  on_short_press(i, dur);
270	                }
271	            }
272	        }
273	    }
274	
275	  close(fd);
276	  return 0;
277	}
