230	/****************************************************************************
231	 * Name: btn_interrupt
232	 ****************************************************************************/
233	
234	static void btn_interrupt(FAR const struct btn_lowerhalf_s *lower,
235	                          FAR void *arg)
236	{
237	  FAR struct btn_upperhalf_s *priv = (FAR struct btn_upperhalf_s *)arg;
238	
239	  DEBUGASSERT(priv);
240	
241	  /* Process the next sample */
242	
243	#if CONFIG_INPUT_BUTTONS_DEBOUNCE_DELAY
244	  wd_start(&priv->bu_wdog, MSEC2TICK(CONFIG_INPUT_BUTTONS_DEBOUNCE_DELAY),
245	           btn_sample, (wdparm_t)priv);
246	#else
247	  btn_sample((wdparm_t)priv);
248	#endif
249	}
250	
251	/****************************************************************************
252	 * Name: btn_sample
253	 ****************************************************************************/
254	
255	static void btn_sample(wdparm_t arg)
256	{
257	  FAR struct btn_upperhalf_s *priv;
258	  FAR const struct btn_lowerhalf_s *lower;
259	  FAR struct btn_open_s *opriv;
260	  btn_buttonset_t sample;
261	  btn_buttonset_t change;
262	  btn_buttonset_t press;
263	  btn_buttonset_t release;
264	  irqstate_t flags;
265	
266	  priv = (FAR struct btn_upperhalf_s *)arg;
267	  DEBUGASSERT(priv && priv->bu_lower);
268	  lower = priv->bu_lower;
269	
270	  /* Sample the new button state */
271	
272	  DEBUGASSERT(lower->bl_buttons);
273	  sample = lower->bl_buttons(lower);
274	
275	  add_ui_randomness(sample);
276	
277	  /* Determine which buttons have been newly pressed and which have been
278	   * newly released.
279	   */
280	
281	  flags = spin_lock_irqsave_nopreempt(&priv->lock);
282	
283	  change = sample ^ priv->bu_sample;
284	  press  = change & sample;
285	
286	  DEBUGASSERT(lower->bl_supported);
287	  release = change & (lower->bl_supported(lower) & ~sample);
288	
289	  /* Visit each opened reference to the device */
290	
291	  for (opriv = priv->bu_open; opriv; opriv = opriv->bo_flink)
292	    {
293	      /* Always set bo_pending true, only clear it after button read */
294	
295	      opriv->bo_pending = true;
296	
297	      /* Have any poll events occurred? */
298	
299	      if ((press & opriv->bo_pollevents.bp_press)     != 0 ||
300	          (release & opriv->bo_pollevents.bp_release) != 0)
301	        {
302	          /* Yes.. Notify all waiters */
303	
304	          poll_notify(opriv->bo_fds, CONFIG_INPUT_BUTTONS_NPOLLWAITERS,
305	                      POLLIN);
306	        }
307	
308	      /* Have any signal events occurred? */
309	
310	      if ((press & opriv->bo_notify.bn_press)     != 0 ||
311	          (release & opriv->bo_notify.bn_release) != 0)
312	        {
313	          /* Yes.. Signal the waiter */
314	
315	          opriv->bo_notify.bn_event.sigev_value.sival_int = sample;
316	          nxsig_notification(opriv->bo_pid, &opriv->bo_notify.bn_event,
317	                             SI_QUEUE, &opriv->bo_work);
318	        }
319	    }
320	
321	  priv->bu_sample = sample;
322	  spin_unlock_irqrestore_nopreempt(&priv->lock, flags);
323	}
