325	/****************************************************************************
326	 * Name: btn_open
327	 ****************************************************************************/
328	
329	static int btn_open(FAR struct file *filep)
330	{
331	  FAR struct inode *inode;
332	  FAR struct btn_upperhalf_s *priv;
333	  FAR struct btn_open_s *opriv;
334	  FAR const struct btn_lowerhalf_s *lower;
335	  btn_buttonset_t supported;
336	  irqstate_t flags;
337	
338	  inode = filep->f_inode;
339	  DEBUGASSERT(inode->i_private);
340	  priv = inode->i_private;
341	
342	  /* Allocate a new open structure */
343	
344	  opriv = kmm_zalloc(sizeof(struct btn_open_s));
345	  if (!opriv)
346	    {
347	      ierr("ERROR: Failed to allocate open structure\n");
348	      return -ENOMEM;
349	    }
350	
351	  /* Initialize the open structure */
352	
353	  lower = priv->bu_lower;
354	  DEBUGASSERT(lower && lower->bl_supported);
355	
356	  supported = lower->bl_supported(lower);
357	  opriv->bo_pollevents.bp_press   = supported;
358	  opriv->bo_pollevents.bp_release = supported;
359	  opriv->bo_pending = true;
360	
361	  /* Attach the open structure to the device */
362	
363	  flags = spin_lock_irqsave(&priv->lock);
364	
365	  opriv->bo_flink = priv->bu_open;
366	  priv->bu_open = opriv;
367	
368	  spin_unlock_irqrestore(&priv->lock, flags);
369	
370	  /* Attach the open structure to the file structure */
371	
372	  filep->f_priv = (FAR void *)opriv;
373	
374	  /* Enable/disable interrupt handling */
375	
376	  btn_enable(priv);
377	
378	  return OK;
