381	/****************************************************************************
382	 * Name: btn_close
383	 ****************************************************************************/
384	
385	static int btn_close(FAR struct file *filep)
386	{
387	  FAR struct inode *inode;
388	  FAR struct btn_upperhalf_s *priv;
389	  FAR struct btn_open_s *opriv;
390	  FAR struct btn_open_s *curr;
391	  FAR struct btn_open_s *prev;
392	  irqstate_t flags;
393	
394	  DEBUGASSERT(filep->f_priv);
395	  opriv = filep->f_priv;
396	  inode = filep->f_inode;
397	  DEBUGASSERT(inode->i_private);
398	  priv  = inode->i_private;
399	
400	  /* Get exclusive access to the driver structure */
401	
402	#if CONFIG_INPUT_BUTTONS_DEBOUNCE_DELAY
403	  wd_cancel(&priv->bu_wdog);
404	#endif
405	
406	  /* Find the open structure in the list of open structures for the device */
407	
408	  flags = spin_lock_irqsave(&priv->lock);
409	
410	  for (prev = NULL, curr = priv->bu_open;
411	       curr && curr != opriv;
412	       prev = curr, curr = curr->bo_flink);
413	
414	  DEBUGASSERT(curr);
415	  if (!curr)
416	    {
417	      spin_unlock_irqrestore(&priv->lock, flags);
418	      ierr("ERROR: Failed to find open entry\n");
419	      return -ENOENT;
420	    }
421	
422	  /* Remove the structure from the device */
423	
424	  if (prev)
425	    {
426	      prev->bo_flink = opriv->bo_flink;
427	    }
428	  else
429	    {
430	      priv->bu_open = opriv->bo_flink;
431	    }
432	
433	  spin_unlock_irqrestore(&priv->lock, flags);
434	
435	  /* Enable/disable interrupt handling */
436	
437	  btn_enable(priv);
438	
439	  /* Cancel any pending notification */
440	
441	  nxsig_cancel_notification(&opriv->bo_work);
442	
443	  /* And free the open structure */
444	
445	  kmm_free(opriv);
446	  return OK;
447	}
