546	/****************************************************************************
547	 * Name: btn_ioctl
548	 ****************************************************************************/
549	
550	static int btn_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
551	{
552	  FAR struct inode *inode;
553	  FAR struct btn_upperhalf_s *priv;
554	  FAR struct btn_open_s *opriv;
555	  FAR const struct btn_lowerhalf_s *lower;
556	  irqstate_t flags;
557	  int ret = OK;
558	
559	  DEBUGASSERT(filep->f_priv);
560	  opriv = filep->f_priv;
561	  inode = filep->f_inode;
562	  DEBUGASSERT(inode->i_private);
563	  priv  = inode->i_private;
564	
565	  /* Handle the ioctl command */
566	
567	  ret = -EINVAL;
568	  switch (cmd)
569	    {
570	    /* Command:     BTNIOC_SUPPORTED
571	     * Description: Report the set of button events supported by the
572	     *              hardware;
573	     * Argument:    A pointer to writeable integer value in which to return
574	     *              the set of supported buttons.
575	     * Return:      Zero (OK) on success.  Minus one will be returned on
576	     *              failure with the errno value set appropriately.
577	     */
578	
579	    case BTNIOC_SUPPORTED:
580	      {
581	        FAR btn_buttonset_t *supported =
582	          (FAR btn_buttonset_t *)((uintptr_t)arg);
583	
584	        if (supported)
585	          {
586	            lower = priv->bu_lower;
587	            DEBUGASSERT(lower && lower->bl_supported);
588	
589	            *supported = lower->bl_supported(lower);
590	            ret = OK;
591	          }
592	      }
593	      break;
594	
595	    /* Command:     BTNIOC_POLLEVENTS
596	     * Description: Specify the set of button events that can cause a poll()
597	     *              to awaken.  The default is all button depressions and
598	     *              all button releases (all supported buttons);
599	     * Argument:    A read-only pointer to an instance of struct
600	     *              btn_pollevents_s
601	     * Return:      Zero (OK) on success.  Minus one will be returned on
602	     *              failure with the errno value set appropriately.
603	     */
604	
605	    case BTNIOC_POLLEVENTS:
606	      {
607	        FAR struct btn_pollevents_s *pollevents =
608	          (FAR struct btn_pollevents_s *)((uintptr_t)arg);
609	
610	        if (pollevents)
611	          {
612	            /* Save the poll events */
613	
614	            flags = spin_lock_irqsave(&priv->lock);
615	
616	            opriv->bo_pollevents.bp_press   = pollevents->bp_press;
617	            opriv->bo_pollevents.bp_release = pollevents->bp_release;
618	
619	            spin_unlock_irqrestore(&priv->lock, flags);
620	
621	            /* Enable/disable interrupt handling */
622	
623	            btn_enable(priv);
624	            ret = OK;
625	          }
626	      }
627	      break;
628	
629	    /* Command:     BTNIOC_REGISTER
630	     * Description: Register to receive a signal whenever there is a change
631	     *              in any of the discrete buttone inputs.  This feature,
632	     *              of course, depends upon interrupt GPIO support from the
633	     *              platform.
634	     * Argument:    A read-only pointer to an instance of struct
635	     *              btn_notify_s
636	     * Return:      Zero (OK) on success.  Minus one will be returned on
637	     *              failure with the errno value set appropriately.
638	     */
639	
640	    case BTNIOC_REGISTER:
641	      {
642	        FAR struct btn_notify_s *notify =
643	          (FAR struct btn_notify_s *)((uintptr_t)arg);
644	
645	        if (notify)
646	          {
647	            /* Save the notification events */
648	
649	            flags = spin_lock_irqsave(&priv->lock);
650	
651	            opriv->bo_notify.bn_press   = notify->bn_press;
652	            opriv->bo_notify.bn_release = notify->bn_release;
653	            opriv->bo_notify.bn_event   = notify->bn_event;
654	            opriv->bo_pid               = nxsched_getpid();
655	
656	            spin_unlock_irqrestore(&priv->lock, flags);
657	
658	            /* Enable/disable interrupt handling */
659	
660	            btn_enable(priv);
661	            ret = OK;
662	          }
663	      }
664	      break;
665	
666	    default:
667	      iinfo("ERROR: Unrecognized command: %d\n", cmd);
668	      ret = -ENOTTY;
669	      break;
670	    }
671	
672	  return ret;
673	}
