772	/****************************************************************************
773	 * Name: btn_register
774	 *
775	 * Description:
776	 *   Bind the lower half button driver to an instance of the upper half
777	 *   button driver and register the composite character driver as the
778	 *   specified device.
779	 *
780	 * Input Parameters:
781	 *   devname - The name of the button device to be registered.
782	 *     This should be a string of the form "/dev/btnN" where N is the
783	 *     minor device number.
784	 *   lower - An instance of the platform-specific button lower half driver.
785	 *
786	 * Returned Value:
787	 *   Zero (OK) is returned on success.  Otherwise a negated errno value is
788	 *   returned to indicate the nature of the failure.
789	 *
790	 ****************************************************************************/
791	
792	int btn_register(FAR const char *devname,
793	                 FAR const struct btn_lowerhalf_s *lower)
794	{
795	  FAR struct btn_upperhalf_s *priv;
796	  int ret;
797	
798	  DEBUGASSERT(devname && lower);
799	
800	  /* Allocate a new button driver instance */
801	
802	  priv = (FAR struct btn_upperhalf_s *)
803	    kmm_zalloc(sizeof(struct btn_upperhalf_s));
804	  if (!priv)
805	    {
806	      ierr("ERROR: Failed to allocate device structure\n");
807	      return -ENOMEM;
808	    }
809	
810	  spin_lock_init(&priv->lock);
811	  nxmutex_init(&priv->mutex);
812	
813	  /* Make sure that all button interrupts are disabled */
814	
815	  DEBUGASSERT(lower->bl_enable);
816	  lower->bl_enable(lower, 0, 0, NULL, NULL);
817	
818	  /* Initialize the new button driver instance */
819	
820	  priv->bu_lower = lower;
821	
822	  /* And register the button driver */
823	
824	  ret = register_driver(devname, &g_btn_fops, 0666, priv);
825	  if (ret < 0)
826	    {
827	      ierr("ERROR: register_driver failed: %d\n", ret);
828	      nxmutex_destroy(&priv->mutex);
829	      kmm_free(priv);
830	    }
831	
832	  return ret;
833	}
