17	/*
18	 * key_manager.c — AP-side S2/S3 context-sensitive keys (路 B M5).
19	 *
20	 * S1 is hold-to-talk (ptt_button.c).  This thread opens its own /dev/btn0
21	 * descriptor (button_upper.c's bu_open is a linked list, so multiple opens
22	 * coexist) and watches the two remaining user keys S2 (bit 1) and S3 (bit 2)
23	 * for short/long press edges, then dispatches:
24	 *
25	 *   short → context action: if a remote permission request is pending, the
26	 *           press is an approval decision (S2 = once, S3 = deny) and dismisses
27	 *           the approval page; otherwise it scrolls the chat transcript
28	 *           (S2 = up/older, S3 = down/newer).
29	 *   long  → S2 cycles the remote agent's model; S3 opens a fresh session.
30	 *
31	 * A long press is still edge-driven: the duration is measured between the
32	 * press and release edges in this single thread, so no separate timer is
33	 * needed and the release always lands on the same thread that saw the press.
34	 *
35	 * Only compiled under CONFIG_AI_AGENT_KEYMGR.  Remote-control calls are
36	 * guarded by CONFIG_AI_AGENT_REMOTE_CTRL and UI calls by LVGL_UI/UI_RPMSG,
37	 * so the same source builds whether or not the remote channel is present.
38	 */
