100	static inline uint64_t key_now_ms(void)
101	{
102	    struct timespec ts;
103	    clock_gettime(CLOCK_MONOTONIC, &ts);
104	    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
105	}
