112	/* ── short press: context action ───────────────────────────────────── */
113	
114	static void key_short_press(int idx)
115	{
116	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
117	    /* A pending permission request redefines the short press: S2 approves
118	     * once, S3 denies.  The approval page (driven by remote_ctrl_channel's
119	     * on_session_event) has already told the user this is the live meaning. */
120	    struct remote_status_s st;
121	    if (remote_ctrl_channel_status(&st) == OK && st.has_prompt) {
122	        enum remote_decision_e d = (idx == KEYMGR_IDX_S2)
123	                                     ? REMOTE_DECISION_ONCE
124	                                     : REMOTE_DECISION_DENY;
125	        (void)remote_ctrl_channel_decide(d);
126	#if KEYMGR_HAVE_UI
127	        /* Dismiss the page immediately — the bridge snapshot that clears the
128	         * prompt can lag, and the user just saw their decision registered. */
129	        (void)lvgl_ui_channel_clear_approval();
130	#endif
131	        syslog(LOG_INFO, "[%s] S%d short → %s\n", TAG, idx,
132	               d == REMOTE_DECISION_ONCE ? "approve-once" : "deny");
133	        return;
134	    }
135	#endif
136	
137	#if KEYMGR_HAVE_UI
138	    /* No approval: scroll the chat transcript. S2 up (older), S3 down (newer). */
139	    int dir = (idx == KEYMGR_IDX_S2) ? 0 : 1;
140	    (void)lvgl_ui_channel_scroll(dir);
141	    syslog(LOG_INFO, "[%s] S%d short → scroll %s\n", TAG, idx,
142	           dir == 0 ? "up" : "down");
143	#else
144	    syslog(LOG_INFO, "[%s] S%d short (no UI channel)\n", TAG, idx);
145	#endif
146	}
