148	/* ── long press: model / session ───────────────────────────────────── */
149	
150	static void key_long_press(int idx)
151	{
152	    if (idx == KEYMGR_IDX_S2) {
153	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
154	        /* Cycle to the next model the bridge offers.  The list is display-only
155	         * authority: the bridge still validates the name, so a stale entry is
156	         * refused rather than silently misapplied. */
157	        static struct remote_model_view_s mv;
158	        if (remote_ctrl_channel_model_view(&mv) == OK && mv.count > 0) {
159	            int cur = -1;
160	            int i;
161	            for (i = 0; i < mv.count; i++) {
162	                if (strcmp(mv.options[i], mv.current) == 0) {
163	                    cur = i;
164	                    break;
165	                }
166	            }
167	            int next = (cur + 1) % mv.count;
168	            (void)remote_ctrl_channel_select_model(mv.options[next]);
169	#if KEYMGR_HAVE_UI
170	            char body[REMOTE_MODEL_MAX + 16];
171	            snprintf(body, sizeof(body), "model: %s", mv.options[next]);
172	            lvgl_toast_show_async("Model", body, 0x4caf50, 2500);
173	#endif
174	            syslog(LOG_INFO, "[%s] S2 long → model %s\n", TAG, mv.options[next]);
175	        } else {
176	            syslog(LOG_WARNING, "[%s] S2 long → no model list\n", TAG);
177	        }
178	#else
179	        syslog(LOG_INFO, "[%s] S2 long (remote ctrl off)\n", TAG);
180	#endif
181	    } else {
182	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
183	        (void)remote_ctrl_channel_new_session();
184	#if KEYMGR_HAVE_UI
185	        lvgl_toast_show_async("Session", "new session", 0x4caf50, 2500);
186	#endif
187	        syslog(LOG_INFO, "[%s] S3 long → new session\n", TAG);
188	#else
189	        syslog(LOG_INFO, "[%s] S3 long (remote ctrl off)\n", TAG);
190	#endif
191	    }
192	}
