59	uint32_t board_button_initialize(void)
60	{
61	  unsigned int id;
62	  int ret;
63	
64	  for (id = 0; id < NUM_BUTTONS; id++)
65	    {
66	      ret = bk7258_gpio_config_input(g_button_pins[id],
67	                                     BK7258_GPIO_PULL_UP);
68	      if (ret < 0)
69	        {
70	          syslog(LOG_ERR, "BK7258 btn: GPIO%d configuration failed: %d\n",
71	                 g_button_pins[id], ret);
72	          return 0;
73	        }
74	    }
75	
76	#ifdef CONFIG_ARCH_IRQBUTTONS
77	  ret = bk7258_gpio_irq_initialize();
78	  if (ret < 0)
79	    {
80	      syslog(LOG_ERR, "BK7258 btn: GPIO IRQ initialization failed: %d\n",
81	             ret);
82	      return 0;
83	    }
84	#endif
85	
86	  return NUM_BUTTONS;
87	}
