89	uint32_t board_buttons(void)
90	{
91	  uint32_t buttons = 0;
92	  unsigned int id;
93	
94	  for (id = 0; id < NUM_BUTTONS; id++)
95	    {
96	      if (!bk7258_gpio_read(g_button_pins[id]))
97	        {
98	          buttons |= g_button_bits[id];
99	        }
100	    }
101	
102	  return buttons;
103	}
