106	int board_button_irq(int id, xcpt_t irqhandler, void *arg)
107	{
108	  unsigned int pin;
109	  int ret;
110	
111	  if (id < 0 || id >= NUM_BUTTONS)
112	    {
113	      return -EINVAL;
114	    }
115	
116	  pin = g_button_pins[id];
117	
118	  if (irqhandler == NULL)
119	    {
120	      bk7258_gpio_irq_disable(pin);
121	      ret = bk7258_gpio_irq_attach(pin, NULL, NULL);
122	      if (ret < 0)
123	        {
124	          syslog(LOG_ERR, "BK7258 btn: GPIO%d IRQ detach failed: %d\n",
125	                 pin, ret);
126	        }
127	
128	      return ret;
129	    }
130	
131	  ret = bk7258_gpio_irq_attach(pin, irqhandler, arg);
132	  if (ret < 0)
133	    {
134	      syslog(LOG_ERR, "BK7258 btn: GPIO%d IRQ attach failed: %d\n",
135	             pin, ret);
136	      return ret;
137	    }
138	
139	  ret = bk7258_gpio_irq_enable(pin, true, true);
140	  if (ret < 0)
141	    {
142	      bk7258_gpio_irq_disable(pin);
143	      (void)bk7258_gpio_irq_attach(pin, NULL, NULL);
144	      syslog(LOG_ERR, "BK7258 btn: GPIO%d IRQ enable failed: %d\n",
145	             pin, ret);
146	    }
147	
148	  return ret;
149	}
