83	static int tokenise(char* line, char** argv, int max_argc)
84	{
85	    int argc = 0;
86	    char* tok = strtok(line, " \t\r\n");
87	    while (tok && argc < max_argc) {
88	        argv[argc++] = tok;
89	        tok = strtok(NULL, " \t\r\n");
90	    }
91	    return argc;
92	}
