251	static void cmd_net_diag(int argc, char** argv)
252	{
253	    if (argc < 2) {
254	        /* Basic diagnostics */
255	        printf("=== Network Diagnostics ===\n");
256	        printf("Interface: %s\n",
257	            network_is_connected() ? "UP" : "DOWN");
258	        printf("IP: %s\n", network_get_ip());
259	        printf("State: %s\n",
260	            network_get_state() == NET_STATE_CONNECTED
261	                ? "CONNECTED"
262	                : "DISCONNECTED");
263	        printf("IOB: %d%%\n", network_get_iob_usage());
264	        printf("===========================\n");
265	        return;
266	    }
267	
268	    if (strcmp(argv[1], "ping") == 0 && argc >= 3) {
269	        /* NuttX does not provide libc system() unless CONFIG_SYSTEM_SYSTEM
270	         * is enabled; call the ping builtin's entry directly instead of
271	         * shelling out, so this diagnostic links without that dependency. */
272	#ifdef CONFIG_SYSTEM_PING
273	        extern int ping_main(int argc, FAR char *argv[]);
274	        FAR char *pargs[] = {"ping", "-c", "3", argv[2], NULL};
275	        ping_main(4, pargs);
276	#else
277	        printf("ping builtin off (CONFIG_SYSTEM_PING); run at NSH: ping -c 3 %s\n",
278	               argv[2]);
279	#endif
280	    } else if (strcmp(argv[1], "http") == 0 && argc >= 3) {
281	        printf("HTTP HEAD %s ...\n", argv[2]);
282	        /* Simple connectivity test using existing TLS layer */
283	        char resp[256] = { 0 };
284	        struct timespec t0, t1;
285	        clock_gettime(CLOCK_MONOTONIC, &t0);
286	        int status = vela_https_get(argv[2], "443", "/",
287	            resp, sizeof(resp));
288	        clock_gettime(CLOCK_MONOTONIC, &t1);
289	        long ms = (t1.tv_sec - t0.tv_sec) * 1000L
290	            + (t1.tv_nsec - t0.tv_nsec) / 1000000L;
291	        printf("Status: %d, Latency: %ldms\n", status, ms);
292	    } else {
293	        printf("Usage: net_diag [ping <host> | http <host>]\n");
294	    }
295	}
296	#endif
