733	
734	#ifdef CONFIG_AI_AGENT_MCP
735	static void cmd_mcp_add(int argc, char** argv)
736	{
737	    /* Two forms:
738	     *   mcp_add <name> <url> [token]                          (generic / Gerrit)
739	     *   mcp_add <name> <url> <jira_url> <username> <pat>      (Jira MCP)
740	     * The Jira form is selected when the URL targets acc.pt.miui.com; the
741	     * Jira MCP (mcp-atlassian) authenticates via three X-Atlassian-* headers
742	     * instead of a single bearer token. */
743	    bool is_jira = (argc >= 3) && (strstr(argv[2], "acc.pt.miui.com") != NULL);
744	
745	    if (argc < 3) {
746	        printf("Usage:\n"
747	               "  mcp_add <name> <url> [token]\n"
748	               "  mcp_add <name> <url> <jira_url> <username> <pat>   (Jira)\n"
749	               "    name:     server name (e.g. gerrit, jira)\n"
750	               "    url:      MCP endpoint\n"
751	               "    token:    optional bearer token (generic / onedev gateway)\n"
752	               "    jira_url: Jira base URL (e.g. https://jira-phone.mioffice.cn)\n"
753	               "    username: Jira username (email prefix)\n"
754	               "    pat:      Jira personal access token\n");
755	        return;
756	    }
757	
758	    int ret;
759	    if (is_jira) {
760	        if (argc < 6) {
761	            printf("Jira MCP needs: mcp_add <name> <url> <jira_url> <username> <pat>\n");
762	            return;
763	        }
764	        ret = mcp_client_add_server(argv[1], argv[2], NULL,
765	            argv[3], argv[4], argv[5]);
766	    } else {
767	        const char* token = (argc >= 4) ? argv[3] : NULL;
768	        ret = mcp_client_add_server(argv[1], argv[2], token,
769	            NULL, NULL, NULL);
770	    }
771	    if (ret == OK) {
772	        printf("Added MCP server: %s → %s\n", argv[1], argv[2]);
773	        /* Persist so the server is auto-restored after reboot. */
774	        mcp_client_persist_save();
775	    } else {
776	        printf("Failed to add MCP server\n");
777	    }
778	}
