832	    if (!json) {
833	        printf("No remote tools (run mcp_discover first)\n");
834	        return;
835	    }
836	
837	    /* One tool per line: the array is thousands of bytes of JSON and a
838	     * single printf gets cut off by the serial console mid-object, which
839	     * is exactly where the tool names live.
840	     */
841	
842	    cJSON* arr = cJSON_Parse(json);
843	    if (!arr || !cJSON_IsArray(arr)) {
844	        printf("%s\n", json);
845	        free(json);
846	        return;
847	    }
848	
849	    cJSON* t = NULL;
850	    int n = 0;
851	    cJSON_ArrayForEach(t, arr)
852	    {
853	        cJSON* name = cJSON_GetObjectItem(t, "name");
854	        cJSON* desc = cJSON_GetObjectItem(t, "description");
855	        const char* d = (desc && cJSON_IsString(desc)) ? desc->valuestring : "";
856	        printf("%2d  %-40s  %.60s\n", ++n,
857	            (name && cJSON_IsString(name)) ? name->valuestring : "?",
858	            d);
859	    }
860	
861	    printf("(%d tools)\n", n);
862	    cJSON_Delete(arr);
863	    free(json);
864	}
