896	static void cmd_notify_inject(int argc, char** argv)
897	{
898	    /* notify_inject <gerrit|jira> <key> <summary...>
899	     * Bypasses polling — pops a toast immediately.  Used to verify the
900	     * toast widget + outbound path without a live MCP server. */
901	    if (argc < 4) {
902	        printf("Usage: notify_inject <gerrit|jira> <key> <summary...>\n"
903	               "  e.g. notify_inject gerrit 9688768 \"CI failed: audio.c build error\"\n");
904	        return;
905	    }
906	
907	    notify_source_t src;
908	    if (strcmp(argv[1], "gerrit") == 0) {
909	        src = NOTIFY_SRC_GERRIT;
910	    } else if (strcmp(argv[1], "jira") == 0) {
911	        src = NOTIFY_SRC_JIRA;
912	    } else {
913	        printf("Source must be 'gerrit' or 'jira'\n");
914	        return;
915	    }
