917	    /* Rejoin argv[3..] as the summary text. */
918	    char summary[192];
919	    summary[0] = '\0';
920	    for (int i = 3; i < argc; i++) {
921	        if (i > 3) strlcat(summary, " ", sizeof(summary));
922	        strlcat(summary, argv[i], sizeof(summary));
923	    }
924	
925	    if (notify_service_inject(src, argv[2], summary) == OK) {
926	        printf("Injected %s notification: %s\n", argv[1], argv[2]);
927	    } else {
