933	/* ── install_skill: install a skill from URL ──────────────── */
934	
935	static void cmd_install_skill(int argc, char** argv)
936	{
937	    if (argc < 3) {
938	        printf("Usage: install_skill <name> <url>\n"
939	               "  name: skill filename (without .md)\n"
940	               "  url:  HTTPS URL to download skill markdown\n");
941	        return;
942	    }
943	
944	    const char* name = argv[1];
945	    const char* url = argv[2];
946	
947	    /* Validate name (lowercase + digits + hyphens) */
948	    for (const char* p = name; *p; p++) {
949	        if (!(*p >= 'a' && *p <= 'z') && !(*p >= '0' && *p <= '9')
950	            && *p != '-' && *p != '_') {
951	            printf("Invalid skill name: use a-z, 0-9, hyphens\n");
952	            return;
953	        }
954	    }
955	
956	    /* Validate URL starts with https:// */
957	    if (strncmp(url, "https://", 8) != 0) {
958	        printf("Only HTTPS URLs are allowed\n");
959	        return;
960	    }
961	
962	    char path[128];
963	    int n = snprintf(path, sizeof(path), "%s%s.md",
964	        AGENT_SKILLS_DIR, name);
965	    if (n < 0 || (size_t)n >= sizeof(path)) {
966	        printf("Skill name too long\n");
967	        return;
968	    }
969	
970	    char* buf = malloc(8192);
971	    if (!buf) {
972	        printf("OOM\n");
973	        return;
974	    }
975	
976	    memset(buf, 0, 8192);
977	    int rc = vela_https_get(url, "443", NULL, buf, 8192);
978	    if (rc < 200 || rc >= 300) {
979	        printf("Download failed: HTTP %d\n", rc);
980	        free(buf);
981	        return;
982	    }
983	
984	    /* Validate content looks like a markdown skill file */
985	    if (buf[0] == '\0') {
986	        printf("Downloaded content is empty\n");
987	        free(buf);
988	        return;
989	    }
990	
991	    /* Basic content validation: must start with # or --- (frontmatter) */
992	    const char* p = buf;
993	    while (*p == ' ' || *p == '\n' || *p == '\r')
994	        p++;
995	    if (*p != '#' && strncmp(p, "---", 3) != 0) {
996	        printf("Invalid skill format: must start with # or ---\n");
997	        free(buf);
998	        return;
999	    }
1000	
1001	    /* Size sanity check */
1002	    size_t content_len = strlen(buf);
1003	    if (content_len < 10) {
1004	        printf("Downloaded content too small (%zu bytes)\n", content_len);
1005	        free(buf);
1006	        return;
1007	    }
1008	
1009	    FILE* f = fopen(path, "w");
1010	    if (!f) {
1011	        printf("Cannot write: %s\n", path);
1012	        free(buf);
1013	        return;
1014	    }
1015	
1016	    fputs(buf, f);
1017	    fclose(f);
1018	    free(buf);
1019	    printf("Skill installed: %s (%zu bytes)\n", path, content_len);
1020	}
