1037	static void* cli_thread(void* arg)
1038	{
1039	    (void)arg;
1040	    char line[LINE_LEN];
1041	    char* argv[MAX_ARGS];
1042	
1043	    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
1044	    pthread_mutex_lock(&g_stdout_lock);
1045	    printf("vela> ");
1046	    fflush(stdout);
1047	    pthread_mutex_unlock(&g_stdout_lock);
1048	
1049	    while (fgets(line, sizeof(line), stdin) != NULL) {
1050	        /* Strip trailing newline */
1051	        size_t len = strlen(line);
1052	        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
1053	            line[--len] = '\0';
1054	
1055	        if (len == 0) {
1056	            pthread_mutex_lock(&g_stdout_lock);
1057	            printf("vela> ");
1058	            fflush(stdout);
1059	            pthread_mutex_unlock(&g_stdout_lock);
1060	            continue;
1061	        }
1062	
1063	        /* syslog and this fgets() share one console, so a log line can land
1064	         * in the read buffer and get dispatched as a command (board:
1065	         * "Unknown command: [agent]").  Every logger here tags its lines
1066	         * "[something]", so anything that opens with '[' is noise, not a
1067	         * typed command -- drop it and re-prompt.
1068	         */
1069	
1070	        {
1071	            const char* q = line;
1072	            while (*q == ' ' || *q == '\t') q++;
1073	            if (*q == '[') {
1074	                pthread_mutex_lock(&g_stdout_lock);
1075	                printf("vela> ");
1076	                fflush(stdout);
1077	                pthread_mutex_unlock(&g_stdout_lock);
1078	                continue;
1079	            }
1080	        }
1081	
1082	        /* Free-text commands (ask/rask/memory_write/voice_test_speak) read
1083	         * the untokensed remainder of the line, captured first because
1084	         * tokenise() splits the buffer in place and caps at MAX_ARGS words —
1085	         * without this, everything past the 7th word of a prompt was
1086	         * silently dropped. */
1087	        char rest[LINE_LEN];
1088	        {
1089	            const char* p = line;
