80	/* Invoked by the session with its lock held: keep this cheap and never call
81	 * back into remote_session_*. */
82	static void on_session_event(void* context, enum remote_event_e event,
83	    const char* text)
84	{
85	    (void)context;
86	
87	    switch (event) {
88	    case REMOTE_EVENT_STATE:
89	        /* A status line and nothing else: what the agent is doing, never what it
90	         * said. The bridge holds to the same rule on its side, so this reports
91	         * "Agent working", a tool name, or "Agent replying" — the reply itself
92	         * arrives as REMOTE_EVENT_TURN_TRANSCRIPT once the turn ends.
93	         *
94	         * The prefix is what makes the line readable. A bare tool name or a
95	         * bare tool argument says nothing about which of those it is, and the
96	         * approval line is the one a person must react to right now -- it
97	         * names the key. */
98	        {
99	            const char *tag = "[状态]";
100	            char body[160];
101	
102	            if (text != NULL && strncmp(text, "approval required: ", 19) == 0) {
103	                tag = "[需要审批]";
104	                snprintf(body, sizeof(body),
105	                         "%s   ->  按 S2 通过 / S3 取消", text + 19);
106	            } else if (text != NULL && strstr(text, "completed") != NULL) {
107	                tag = "[工具]";
108	                snprintf(body, sizeof(body), "%s", text);
109	            } else if (text != NULL &&
110	                       (strcmp(text, "Agent working") == 0 ||
111	                        strcmp(text, "Agent replying") == 0)) {
112	                tag = "[任务]";
113	                snprintf(body, sizeof(body), "%s",
114	                         strcmp(text, "Agent working") == 0 ? "进行中" : "回复中");
115	            } else if (text != NULL && strncmp(text, "Agent turn", 10) == 0) {
116	                tag = "[任务]";
117	                snprintf(body, sizeof(body), "%s", text + 11);
118	            } else {
119	                snprintf(body, sizeof(body), "%s", text != NULL ? text : "");
120	            }
121	
122	            syslog(LOG_INFO, "[%s] %s %s\n", TAG, tag, body);
123	            notify_observer_state(text);
124	        }
125	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
126	        /* Reflect the authority latch onto the approval page: show it the
127	         * moment a permission request is pending, dismiss it once the prompt
128	         * clears (decided locally, timed out, or resolved from the dashboard).
129	         * Reading link state directly is safe — this handler runs with the
130	         * session lock held and must not re-enter the session, so we never call
131	         * remote_ctrl_channel_status() here (it would re-lock and deadlock). */
132	        if (g_session.link.has_prompt) {
133	            lvgl_ui_channel_set_approval(g_session.link.prompt.tool,
134	                                         g_session.link.prompt.hint);
135	        } else {
136	            lvgl_ui_channel_clear_approval();
137	        }
138	#endif
139	        break;
140	
141	    case REMOTE_EVENT_AGENT_OUTPUT:
142	        /* Deliberately silent. A chunk lands every few tens of milliseconds and
143	         * splits mid-sentence, so logging one line per chunk filled the console
144	         * without saying anything the 'Agent replying' status line above has not
145	         * already said. The link accumulates them; the reply prints once, below. */
146	        break;
147	
148	    case REMOTE_EVENT_TURN_TRANSCRIPT:
149	        /* One call for the whole reply, not one per line. nx_vsyslog stamps its
150	         * prefix once per call, so printing line by line turned a reply into a
151	         * column of timestamped log records; passing the text in one go lets its
152	         * own newlines through and it reads as the block it is.
153	         *
154	         * No trailing newline here: nx_vsyslog appends one when the text does not
155	         * already end in it, so adding one would leave a blank line behind every
156	         * reply. Length is not a concern — CONFIG_SYSLOG_BUFFER is off on this
157	         * board, so the raw stream writes straight through with no fixed buffer
158	         * to truncate against. */
159	        /* agent_main.c already prints the reply to the console.  Logging
160	         * the whole body here printed it a second time on a board where
161	         * syslog shares that console.
162	         */
163	
164	        syslog(LOG_INFO, "[%s] reply %u bytes\n", TAG,
165	            text != NULL ? (unsigned)strlen(text) : 0u);
166	        notify_observer_reply(text);
167	        /* rask-initiated turns also ride the cli outbound branch so the reply
168	         * lands where an `ask` reply lands: console card, LVGL chat view and
169	         * the voice pipeline behind it. Cheap by design — one heap copy and a
170	         * ring-buffer push; no remote_session_* reentry. `rreply` still reads
171	         * the session transcript, so nothing is lost if the push fails. */
172	        if (g_mirror_turn && text != NULL && text[0] != '\0') {
173	            agent_msg_t msg;
174	            memset(&msg, 0, sizeof(msg));
175	            strncpy(msg.channel, "cli", sizeof(msg.channel) - 1);
176	            msg.content = strdup(text);
177	            if (msg.content != NULL) {
178	                if (message_bus_push_outbound(&msg) != OK)
179	                    free(msg.content);
180	            }
181	            g_mirror_turn = false;
182	        }
183	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
184	        /* A remote coding turn runs for minutes and the user walked away —
185	         * the approval toast (above) already owns the "needs you" case; this
186	         * one says the wait is over. Voice is already covered by the mirror
187	         * branch, so the toast only needs the first line of the reply. */
188	        if (text != NULL && text[0] != '\0') {
189	            char body[112];

195	#endif
196	#else
197	  bk7258_ap_initialize();
198	#endif
199	}
