247	
248	#define BK7258_GPIO_OUTPUT_VALUE  (UINT32_C(1) << 1)
249	#define BK7258_GPIO_INPUT_ENABLE  (UINT32_C(1) << 2)
250	#define BK7258_GPIO_OUTPUT_DISABLE (UINT32_C(1) << 3)
251	#define BK7258_GPIO_PULL_MODE     (UINT32_C(1) << 4)
252	#define BK7258_GPIO_PULL_ENABLE   (UINT32_C(1) << 5)
