260	static inline void bk7258_ap_gpio_write(unsigned int pin, uint32_t value)
261	{
262	  *(volatile uint32_t *)BK7258_GPIO_CFG(pin) = value;
263	  __asm__ volatile ("dsb" : : : "memory");
264	}
