266	static void bk7258_ap_heartbeat_led_write(bool on)
267	{
268	  uint32_t config =
269	    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);
270	  bool high = BOARD_AP_HEARTBEAT_LED_ACTIVE_HIGH ? on : !on;
271	
272	  if (high)
273	    {
274	      config |= BK7258_GPIO_OUTPUT_VALUE;
275	    }
276	  else
277	    {
278	      config &= ~BK7258_GPIO_OUTPUT_VALUE;
279	    }
280	
281	  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
282	}
