284	static void bk7258_ap_heartbeat_led_initialize(void)
285	{
286	  uint32_t config =
287	    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);
288	
289	  /* Select ordinary GPIO, disable input and pulls, enable output, and seed the
290	   * inactive level before the task starts toggling the pin. */
291	
292	  config &= ~(BK7258_GPIO_OUTPUT_VALUE |
293	              BK7258_GPIO_INPUT_ENABLE |
294	              BK7258_GPIO_OUTPUT_DISABLE |
295	              BK7258_GPIO_PULL_MODE |
296	              BK7258_GPIO_PULL_ENABLE |
297	              BK7258_GPIO_SECOND_FUNC);
298	  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
299	  bk7258_ap_heartbeat_led_write(false);
300	}
