317	int key_manager_start(void)
318	{
319	    pthread_t tid;
320	    pthread_attr_t attr;
321	    struct sched_param sp;
322	    int ret;
323	
324	    if (g_key_running) {
325	        return 0;
326	    }
327	
328	    ret = pthread_attr_init(&attr);
329	    if (ret != 0) {
330	        syslog(LOG_ERR, "[%s] attr_init: %d\n", TAG, ret);
331	        return -ret;
332	    }
333	    sp.sched_priority = CONFIG_AI_AGENT_KEYMGR_PRIORITY;
334	    (void)pthread_attr_setschedpolicy(&attr, SCHED_RR);
335	    (void)pthread_attr_setschedparam(&attr, &sp);
336	    (void)pthread_attr_setstacksize(&attr, CONFIG_AI_AGENT_KEYMGR_STACKSIZE);
337	
338	    ret = pthread_create(&tid, &attr, key_manager_thread, NULL);
339	    (void)pthread_attr_destroy(&attr);
340	    if (ret != 0) {
341	        syslog(LOG_ERR, "[%s] pthread_create: %d\n", TAG, ret);
342	        return -ret;
343	    }
344	
345	    pthread_detach(tid);
346	    g_key_running = true;
347	    syslog(LOG_INFO, "[%s] context-key thread started\n", TAG);
348	    return 0;
349	}
