155	               idx == KEYMGR_IDX_S2 ? "approve-once" : "deny");
156	        return;
157	    }
158	#endif
159	
160	#if KEYMGR_HAVE_UI
161	    /* No approval: scroll the chat transcript. S2 up (older), S3 down (newer). */
162	    int dir = (idx == KEYMGR_IDX_S2) ? 0 : 1;
163	    (void)lvgl_ui_channel_scroll(dir);
164	    syslog(LOG_INFO, "[%s] S%d short → scroll %s\n", TAG, idx,
