217	/* ── watch thread ──────────────────────────────────────────────────── */
218	
219	static void* key_manager_thread(void* arg)
220	{
221	    const char* devpath = CONFIG_AI_AGENT_KEYMGR_DEVPATH;
222	    btn_buttonset_t mask = key_bit(KEYMGR_IDX_S2) | key_bit(KEYMGR_IDX_S3);
223	    struct btn_pollevents_s pe;
224	    struct pollfd pfd;
225	    btn_buttonset_t supported;
226	    btn_buttonset_t last;
227	    bool have_baseline = false;
228	    int fd;
229	    int i;
230	
231	    (void)arg;
232	
233	    fd = open(devpath, O_RDONLY);
234	    if (fd < 0) {
235	        syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
236	        return NULL;
237	    }
238	
239	    supported = 0;
240	    if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0) {
241	        syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
242	        close(fd);
243	        return NULL;
244	    }
245	    if ((supported & mask) != mask) {
246	        syslog(LOG_ERR, "[%s] S2/S3 not all in supported set 0x%08lx\n",
247	               TAG, (unsigned long)supported);
248	        close(fd);
249	        return NULL;
250	    }
251	
252	    pe.bp_press   = mask;
253	    pe.bp_release = mask;
254	    (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
255	
256	    pfd.fd     = fd;
257	    pfd.events = POLLIN;
258	    last       = 0;
259	
260	    syslog(LOG_INFO, "[%s] watching %s S2/S3 (context keys)\n", TAG, devpath);
261	
262	    for (;;) {
263	        btn_buttonset_t cur;
264	        btn_buttonset_t change;
265	        ssize_t nread;
266	
267	        if (poll(&pfd, 1, -1) < 0) {
268	            if (errno == EINTR) {
269	                continue;
270	            }
271	            syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
272	            break;
273	        }
274	        if ((pfd.revents & POLLIN) == 0) {
275	            continue;
276	        }
277	
278	        nread = read(fd, &cur, sizeof(cur));
279	        if (nread != (ssize_t)sizeof(cur)) {
280	            continue;
281	        }
282	        if (!have_baseline) {
283	            last = cur;
284	            have_baseline = true;
285	            continue;
286	        }
287	
288	        change = cur ^ last;
289	        for (i = KEYMGR_IDX_S2; i <= KEYMGR_IDX_S3; i++) {
290	            btn_buttonset_t bit = key_bit(i);
291	            if ((change & bit) == 0) {
292	                continue;
293	            }
294	            if (cur & bit) {
295	                g_held[i] = true;
296	                g_press_ms[i] = key_now_ms();
297	            } else {
298	                if (!g_held[i]) {
299	                    continue;
300	                }
301	                g_held[i] = false;
302	                uint64_t dur = key_now_ms() - g_press_ms[i];
303	                if (dur >= CONFIG_AI_AGENT_KEYMGR_LONG_MS) {
304	                    key_long_press(i);
305	                } else {
306	                    key_short_press(i);
307	                }
308	            }
309	        }
310	        last = cur;
311	    }
312	
313	    close(fd);
314	    return NULL;
315	}
