214	void keyctx_push(const struct keyctx_s *ctx)
215	{
216	  if (s_ctx_depth < sizeof(s_ctx_stack) / sizeof(s_ctx_stack[0]))
217	    {
218	      s_ctx_stack[s_ctx_depth++] = ctx;
219	      if (ctx->enter != NULL)
220	        {
221	          ctx->enter();
222	        }
223	    }
224	}
225	
226	void keyctx_pop(void)
227	{
228	  if (s_ctx_depth > 0)
229	    {
230	      const struct keyctx_s *ctx = s_ctx_stack[--s_ctx_depth];
231	      if (ctx->leave != NULL)
232	        {
233	          ctx->leave();
234	        }
235	    }
236	}
237	
238	static const struct keymap_s *keymap_lookup(uint32_t keys,
239	                                            enum gesture_e g,
240	                                            const char **which)
241	{
242	  unsigned int i;
243	
244	  for (i = s_ctx_depth; i > 0; i--)
245	    {
246	      const struct keyctx_s *ctx = s_ctx_stack[i - 1];
247	      unsigned int j;
248	
249	      for (j = 0; j < ctx->nmap; j++)
250	        {
251	          if (ctx->map[j].keys == keys && ctx->map[j].gesture == g)
252	            {
253	              if (which != NULL)
254	                {
255	                  *which = ctx->name;
256	                }
257	
258	              return &ctx->map[j];
259	            }
260	        }
261	    }
262	
263	  for (i = 0; i < g_global_ctx.nmap; i++)
264	    {
265	      if (g_global_ctx.map[i].keys == keys &&
266	          g_global_ctx.map[i].gesture == g)
267	        {
268	          if (which != NULL)
269	            {
270	              *which = g_global_ctx.name;
271	            }
272	
273	          return &g_global_ctx.map[i];
274	        }
275	    }
276	
277	  return NULL;
278	}
