406	/****************************************************************************
407	 * Gesture engine
408	 *
409	 * Works on the state snapshot, not on the event stream.  A key held past
410	 * GESTURE_HOLD_MS fires HOLD once; releasing inside that window and
411	 * pressing again inside GESTURE_DOUBLE_MS upgrades the first tap to DOUBLE.
412	 ****************************************************************************/
413	
414	/* 32-bit arithmetic on purpose: the 64-bit multiply/divide the naive form
415	 * pulls in (umul64_const / div64_const32) is deep enough to blow a 2 KB
416	 * thread stack.  Milliseconds from a 32-bit tick count is enough for the
417	 * gesture deadlines.
418	 */
419	
420	static uint32_t now_ms(void)
421	{
422	  return (uint32_t)(clock() / (CLOCKS_PER_SEC / 1000u));
423	}
424	
425	static void gesture_fire(uint32_t keys, enum gesture_e g)
426	{
427	  const char *which = "-";
428	  const struct keymap_s *m = keymap_lookup(keys, g, &which);
429	
430	  printf("[key] %s: keys=%lx gesture=%d -> %s\n", which,
431	         (unsigned long)keys, g,
432	         (m != NULL && m->fn != NULL) ? "hit" : "unmapped");
433	  if (m != NULL && m->fn != NULL)
434	    {
435	      m->fn();
436	    }
437	}
438	
439	static void gesture_update(uint32_t now)
440	{
441	  uint32_t pressed = s_held & ~s_prev;
442	  uint32_t released = s_prev & ~s_held;
443	  unsigned int i;
444	
445	  /* COMBO: two or more keys down at once.  Fires once on the transition
446	   * and then suppresses the individual TAP/HOLD for every key that took
447	   * part -- otherwise pressing KEY1 then KEY2 would emit COMBO *and* a
448	   * stray KEY1 TAP when KEY1 is released.
449	   */
450	
451	  if (pressed != 0 && (s_held & (s_held - 1)) != 0 && s_combo_started == 0)
452	    {
453	      s_combo_started = s_held;
454	      gesture_fire(s_held, GESTURE_COMBO);
455	    }
456	
457	  for (i = 0; i < KEY_COUNT; i++)
458	    {
459	      uint32_t bit = KEY_BIT(i);
460	
461	      if ((pressed & bit) != 0)
462	        {
463	          s_down_ms[i] = now;
464	          s_hold_fired[i] = false;
465	
466	          /* Only keys that carry a press-and-hold binding emit the edge
467	           * pair.  Firing it for every key made each tap of KEY1/KEY2 log
468	           * "unmapped" for PRESS and RELEASE before the TAP that mattered
469	           * (board: "我都是单击").  TAP/HOLD/DOUBLE/COMBO keep their
470	           * unmapped diagnostic -- those are gestures a person can
471	           * discover by accident, these are not.
472	           */
473	
474	          if (keymap_lookup(bit, GESTURE_PRESS, NULL) != NULL)
475	            {
476	              gesture_fire(bit, GESTURE_PRESS);
477	            }
478	        }
479	
480	      if ((s_combo_started & bit) != 0)
481	        {
482	          /* Consumed by the combo: no single-key gesture for this press, and
483	           * a tap left over from an earlier press of the same key must go
484	           * too -- otherwise it fires after the combo and looks like a stray
485	           * KEY1 tap.
486	           */
487	
488	          s_tap_pending[i] = false;
489	          if ((released & bit) != 0)
490	            {
491	              s_combo_started &= ~bit;
492	            }
493	
494	          continue;
495	        }
496	
497	      /* A key bound to GESTURE_PRESS is a press-and-hold key: the whole
498	       * gesture is the edge pair, so TAP and HOLD must not also fire or
499	       * releasing the PTT key would answer a permission request.
500	       */
501	
502	      if (keymap_lookup(bit, GESTURE_PRESS, NULL) == NULL)
503	        {
504	          if ((s_held & bit) != 0 && !s_hold_fired[i] &&
505	              (uint32_t)(now - s_down_ms[i]) >= GESTURE_HOLD_MS)
506	            {
507	              s_hold_fired[i] = true;
508	              s_tap_pending[i] = false;
509	              gesture_fire(bit, GESTURE_HOLD);
510	            }
511	
512	          if ((released & bit) != 0 && !s_hold_fired[i])
513	            {
514	              gesture_fire(bit, GESTURE_TAP);
515	            }
516	        }
517	
518	      if ((released & bit) != 0 &&
519	          keymap_lookup(bit, GESTURE_RELEASE, NULL) != NULL)
520	        {
521	          gesture_fire(bit, GESTURE_RELEASE);
522	        }
523	    }
524	
525	  /* Reset the combo only after the loop has seen every release edge.
526	   * Clearing it on s_held == 0 beforehand let the last key released skip
527	   * the suppression and emit a stray TAP.
528	   */
529	
530	  if (s_held == 0)
531	    {
532	      s_combo_started = 0;
533	    }
534	
535	  s_prev = s_held;
536	}
537	
538	/****************************************************************************
539	 * button_source
540	 *
541	 * The only place that touches /dev/btn0.  poll() wakes on any edge; read()
542	 * returns the current bitmask, so edges are derived by differencing.
543	 ****************************************************************************/
544	
545	static int button_source_init(void)
546	{
547	  struct btn_pollevents_s ev;
548	
549	  s_fd = open("/dev/btn0", O_RDONLY);
550	  if (s_fd < 0)
551	    {
552	      printf("[key] open /dev/btn0: %d\n", errno);
553	      return -errno;
554	    }
555	
556	  ev.bp_press = ev.bp_release = (1u << KEY_COUNT) - 1u;
557	  ioctl(s_fd, BTNIOC_POLLEVENTS, &ev);
558	  return 0;
559	}
560	
561	static void button_source_poll(void)
562	{
563	  struct pollfd pfd;
564	  btn_buttonset_t set;
565	  ssize_t n;
566	  int ret;
567	
568	  pfd.fd = s_fd;
569	  pfd.events = POLLIN;
570	  ret = poll(&pfd, 1, POLL_SLICE_MS);
571	  (void)ret;
572	
573	  /* gesture_update must run every slice, not only when poll reports data:
574	   * the deferred TAP and the HOLD timer are deadlines, and skipping the
575	   * quiet slices pushed them to the next key event -- which is why a tap
576	   * printed only when something else was pressed afterwards.
577	   *
578	   * The level is sampled every slice for the same reason.  poll() only
579	   * shortens the wait; read() returns the live GPIO level, so a lost edge
580	   * heals within one slice.  Reading only on POLLIN left KEY4 "held" after
581	   * a PTT whose release edge never reached us, and its RELEASE then fired
582	   * on the next KEY1 tap during an approval (board log).
583	   */
584	
585	  n = read(s_fd, &set, sizeof(set));
586	  if (n == sizeof(set))
587	    {
588	      s_held = (uint32_t)set;
589	    }
590	
591	  /* Report an edge the interrupt path never delivered.  The upper half
592	   * debounces for 30 ms before notifying, so a short mismatch is normal;
593	   * only one that outlives 200 ms without POLLIN is a lost edge.
594	   */
595	
596	  if (ret > 0)
597	    {
598	      s_irq_held = s_held;
599	    }
600	
601	  if (s_held != s_irq_held)
602	    {
603	      if (!s_skew)
604	        {
605	          s_skew = true;
606	          s_skew_ms = now_ms();
607	        }
608	      else if (!s_skew_reported &&
609	               (uint32_t)(now_ms() - s_skew_ms) >= 200)
610	        {
611	          s_skew_reported = true;
612	          printf("[key] missed edge: irq=%lx level=%lx\n",
613	                 (unsigned long)s_irq_held, (unsigned long)s_held);
614	          key3_regs("missed edge");
615	        }
616	    }
617	  else
618	    {
619	      s_skew = false;
620	      s_skew_reported = false;
621	    }
622	
623	  gesture_update(now_ms());
624	}
625	
626	/****************************************************************************
627	 * Public Functions
628	 ****************************************************************************/
629	
630	/* Tracks whether the approval context is currently on the stack so the poll
631	 * below only pushes/pops on a transition, not every slice. */
632	static bool s_approval_active;
633	
634	/* Switch the key context when a remote permission request comes and goes.
635	 * Polled once per slice: when pending() says an approval is up, the approval
636	 * map (S2 approve / S3 deny) is pushed over the idle map; when it clears, it
637	 * is popped and the keys go back to scrolling. */
638	static void update_pending_ctx(void)
639	{
640	  bool pending;
641	
642	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
643	  pending = (s_pending != NULL) && s_pending(s_ctx) != 0;
644	#else
645	  pending = false;
646	#endif
647	
648	  if (pending && !s_approval_active)
649	    {
650	      keyctx_push(&g_approval_ctx);
651	      s_approval_active = true;
652	    }
653	  else if (!pending && s_approval_active)
654	    {
655	      keyctx_pop();
656	      s_approval_active = false;
657	    }
658	}
659	
660	static FAR void *key_thread(FAR void *arg)
661	{
662	  (void)arg;
663	
664	  if (button_source_init() < 0)
665	    {
666	      return NULL;
667	    }
668	
669	  extern void bk7258_status_led_step(uint32_t tick_ms);
670	  unsigned int ticks = 0;
671	
672	  keyctx_push(&g_idle_ctx);
673	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
674	  remote_ctrl_register_input(&g_keymap_ops);
675	#endif
676	  printf("[key] input up (%d keys)\n", KEY_COUNT);
677	
678	  for (; ; )
679	    {
680	      update_pending_ctx();
681	      button_source_poll();
682	      if (++ticks >= LED_SLICE_TICKS)
683	        {
684	          ticks = 0;
685	          bk7258_status_led_step(POLL_SLICE_MS * LED_SLICE_TICKS);
686	        }
687	    }
688	
689	  return NULL;
690	}
691	
692	int bk7258_buttons_input_initialize(void)
693	{
694	  pthread_t tid;
695	  pthread_attr_t attr;
696	  int ret;
697	
698	  pthread_attr_init(&attr);
699	  pthread_attr_setstacksize(&attr, 4096);
700	  ret = pthread_create(&tid, &attr, key_thread, NULL);
701	  pthread_attr_destroy(&attr);
702	  return ret == 0 ? 0 : -EIO;
703	}

