375	/****************************************************************************
376	 * Public Functions
377	 ****************************************************************************/
378	
379	FAR struct spi_dev_s *bk7258_spi_initialize(void)
380	{
381	  FAR struct bk7258_spi_dev_s *priv = &g_spidev;
382	  FAR bk7258_spi_hw_t *hw = (FAR bk7258_spi_hw_t *)BK7258_SPI1_BASE;
383	  uint32_t regval;
384	
385	  /* Power up the BAKP domain, which owns SPI1 (0x45880000).  It is gated by
386	   * cpu_power_sleep_wakeup.pwd_bakp (bit 4); while the bit is set the whole
387	   * window reads back 0x60007e07 (the "black screen, two white lines" HW-SPI
388	   * failure).
389	   *
390	   * Use the direct HAL entry sys_hal_module_power_ctrl(), not
391	   * bk_pm_module_vote_power_ctrl(): that vote layer lives in
392	   * hal_port/platform_shim.c under if(CONFIG_BK7258_WIFI) and is therefore
393	   * not linked on this AP core -- the same reason bk7258_psram.c calls the
394	   * HAL entry for AHBP instead.  POWER_MODULE_NAME_BAKP == 4,
395	   * POWER_MODULE_STATE_ON == 0 (sys_types.h:324 and :417); the call clears
396	   * pwd_bakp, the same register write the old direct fallback performed.
397	   */
398	
399	  {
400	    extern void sys_hal_module_power_ctrl(int module, int power_state);
401	
402	    sys_hal_module_power_ctrl(4 /* BAKP */, 0 /* STATE_ON */);
403	  }
404	
405	  /* Enable the SPI1 clock gate and pin the source clock to XTAL 26M. */
406	
407	  regval  = getreg32(BK7258_SYS_DEV_CLK_EN);
408	  regval |= BK7258_SYS_SPI1_CLK_EN;
409	  putreg32(regval, BK7258_SYS_DEV_CLK_EN);
410	
411	  regval  = getreg32(BK7258_SYS_CLKSEL);
412	  regval &= ~BK7258_SYS_SPI1_APLL;
413	  putreg32(regval, BK7258_SYS_CLKSEL);
414	
415	  /* Route SCK (GPIO2) and MOSI (GPIO4) to the SPI1 controller.  CS
416	   * (GPIO3) and D/C (GPIO5) stay plain GPIO outputs.
417	   */
418	
419	  bk7258_gpio_periph(BOARD_LCD_SCL_PIN, BK7258_SPI1_FUNC_SCK);
420	  bk7258_gpio_periph(BOARD_LCD_SDA_PIN, BK7258_SPI1_FUNC_MOSI);
421	  bk7258_gpio_config_output(BOARD_LCD_CS_PIN, false);
422	  bk7258_gpio_config_output(BOARD_LCD_DC_PIN, false);
423	
424	  /* Idle levels: CS de-asserted high, D/C low until a transfer begins. */
425	
426	  bk7258_gpio_write(BOARD_LCD_CS_PIN, true);
427	  bk7258_gpio_write(BOARD_LCD_DC_PIN, false);
428	
429	  /* Bring the controller out of reset.  soft_reset is a low-active reset
430	   * bit: the ARMINO spi_ll_init() sets it to 1 and keeps it there (the
431	   * controller is out of reset while it is 1).  The earlier draft cleared
432	   * it back to 0, which held the shift engine in reset: registers stayed
433	   * writable through AHB but SCK never ran and tx_finish_int never fired.
434	   */
435	
436	  hw->global_ctrl.soft_reset = 1;
437	
438	  hw->ctrl.v = 0;
439	  hw->cfg.v  = 0;
440	  hw->int_status.v = 0xffff;  /* clear sticky status */
441	
442	  /* Mirror the ARMINO spi_hal_configure() interrupt enables. */
443	
444	  hw->ctrl.tx_udf_int_en = 1;
445	  hw->ctrl.rx_ovf_int_en = 1;
446	  hw->ctrl.tx_fifo_int_en = 0;
447	  hw->ctrl.rx_fifo_int_en = 1;
448	
449	  hw->ctrl.master_en    = 1;  /* master role */
450	  hw->ctrl.bit_width    = 0;  /* 8-bit */
451	  hw->ctrl.lsb_first_en = 0;  /* MSB first */
452	  hw->ctrl.wire3_en     = 0;  /* 4-wire (MOSI/MISO) */
453	  hw->ctrl.slave_release_int_en = 1;  /* 4-wire mode, spi_hal_configure() */
454	  hw->ctrl.cpol         = 0;  /* mode 0 */
455	  hw->ctrl.cpha         = 0;
456	
457	  /* ARMINO spi_ll_init() sets these two before spi_hal_configure().  They
458	   * are RX-centric (byte spacing / Rx sample edge) but are reproduced here
459	   * so the controller state matches the reference SDK bit-for-bit.
460	   */
461	
462	  hw->ctrl.byte_interval = 1;  /* bit[24:29] > 0 avoids SPI clock glitches */
463	  hw->ctrl.reserved      = 1;  /* bit[30:31] rx_sample_edge = 1st negedge */
464	
465	  hw->ctrl.enable       = 1;
466	
467	  hw->cfg.tx_finish_int_en = 1;
468	  hw->cfg.rx_finish_int_en = 1;
469	
470	  hw->int_status.tx_fifo_int = 1;        /* write-1-clear */
471	  hw->int_status.rx_fifo_int = 1;        /* write-1-clear */
472	
473	  priv->hw       = hw;
474	  priv->frequency = 0;
475	  priv->actual    = 0;
476	  priv->mode      = SPIDEV_MODE0;
477	  priv->nbits     = 8;
478	  priv->dev.ops   = &g_bk7258_spiops;
479	  nxmutex_init(&priv->lock);
480	
481	  /* Bring-up diagnostic: read back the SPI1 controller and the SCK/MOSI
482	   * mux so a black screen can be localized to (a) the controller config,
483	   * (b) the clock gate, or (c) the pad routing — without a logic analyzer.
484	   * Expected on a healthy config: ctrl=41c100b0 (rx_sample_edge bit30 +
485	   * enable bit23 + master_en bit22 + slave_release_int bit16 +
486	   * byte_interval bit24 + rx_fifo_int bit7 + rx_ovf bit5 + tx_udf bit4;
487	   * clk_rate is still 0 here, set later by setfrequency), global_ctrl=1
488	   * (soft_reset released), CLK_EN bit9 set, SCK/MOSI GPIO_CFG bit6
489	   * (second_func) set, SYS_FUNC0 SCK/MOSI fields 0.
490	   */
491	
492	  printf("SPI1: ctrl=%08x global=%08x dev_status=%08x\n",
493	         (unsigned int)hw->ctrl.v,
494	         (unsigned int)hw->global_ctrl.v,
495	         (unsigned int)hw->dev_status);
496	  printf("SPI1: CLK_EN=%08x CLKSEL=%08x\n",
497	         (unsigned int)getreg32(BK7258_SYS_DEV_CLK_EN),
498	         (unsigned int)getreg32(BK7258_SYS_CLKSEL));
499	  printf("SPI1: GPIO_CFG SCK(2)=%08x MOSI(4)=%08x CS(3)=%08x DC(5)=%08x\n",
500	         (unsigned int)getreg32(BK7258_GPIO_CFG(2)),
501	         (unsigned int)getreg32(BK7258_GPIO_CFG(4)),
502	         (unsigned int)getreg32(BK7258_GPIO_CFG(3)),
503	         (unsigned int)getreg32(BK7258_GPIO_CFG(5)));
504	  printf("SPI1: SYS_FUNC0=%08x SYS_FUNC1=%08x\n",
505	         (unsigned int)getreg32(BK7258_SYS_GPIO_FUNC(2)),
506	         (unsigned int)getreg32(BK7258_SYS_GPIO_FUNC(10)));
507	
508	  return &priv->dev;
509	}
