239	static const struct keymap_s *keymap_lookup(uint32_t keys,
240	                                            enum gesture_e g,
241	                                            const char **which)
242	{
243	  unsigned int i;
244	
245	  for (i = s_ctx_depth; i > 0; i--)
246	    {
247	      const struct keyctx_s *ctx = s_ctx_stack[i - 1];
248	      unsigned int j;
249	
250	      for (j = 0; j < ctx->nmap; j++)
251	        {
252	          if (ctx->map[j].keys == keys && ctx->map[j].gesture == g)
253	            {
254	              if (which != NULL)
255	                {
256	                  *which = ctx->name;
257	                }
258	
259	              return &ctx->map[j];
260	            }
261	        }
262	    }
263	
264	  for (i = 0; i < g_global_ctx.nmap; i++)
265	    {
266	      if (g_global_ctx.map[i].keys == keys &&
267	          g_global_ctx.map[i].gesture == g)
268	        {
269	          if (which != NULL)
270	            {
271	              *which = g_global_ctx.name;
272	            }
273	
274	          return &g_global_ctx.map[i];
275	        }
276	    }
277	
278	  return NULL;
279	}
