407	/****************************************************************************
408	 * Gesture engine
409	 *
410	 * Works on the state snapshot, not on the event stream.  A key held past
411	 * GESTURE_HOLD_MS fires HOLD once; releasing inside that window and
412	 * pressing again inside GESTURE_DOUBLE_MS upgrades the first tap to DOUBLE.
413	 ****************************************************************************/
414	
415	/* 32-bit arithmetic on purpose: the 64-bit multiply/divide the naive form
416	 * pulls in (umul64_const / div64_const32) is deep enough to blow a 2 KB
417	 * thread stack.  Milliseconds from a 32-bit tick count is enough for the
418	 * gesture deadlines.
419	 */
420	
421	static uint32_t now_ms(void)
422	{
423	  return (uint32_t)(clock() / (CLOCKS_PER_SEC / 1000u));
424	}
425	
426	static void gesture_fire(uint32_t keys, enum gesture_e g)
427	{
428	  const char *which = "-";
429	  const struct keymap_s *m = keymap_lookup(keys, g, &which);
430	
431	  printf("[key] %s: keys=%lx gesture=%d -> %s\n", which,
432	         (unsigned long)keys, g,
433	         (m != NULL && m->fn != NULL) ? "hit" : "unmapped");
434	  if (m != NULL && m->fn != NULL)
435	    {
436	      m->fn();
437	    }
438	}
439	
440	static void gesture_update(uint32_t now)
441	{
442	  uint32_t pressed = s_held & ~s_prev;
443	  uint32_t released = s_prev & ~s_held;
444	  unsigned int i;
445	
446	  /* COMBO: two or more keys down at once.  Fires once on the transition
447	   * and then suppresses the individual TAP/HOLD for every key that took
448	   * part -- otherwise pressing KEY1 then KEY2 would emit COMBO *and* a
449	   * stray KEY1 TAP when KEY1 is released.
450	   */
451	
452	  if (pressed != 0 && (s_held & (s_held - 1)) != 0 && s_combo_started == 0)
453	    {
454	      s_combo_started = s_held;
455	      gesture_fire(s_held, GESTURE_COMBO);
456	    }
457	
458	  for (i = 0; i < KEY_COUNT; i++)
459	    {
460	      uint32_t bit = KEY_BIT(i);
461	
462	      if ((pressed & bit) != 0)
463	        {
464	          s_down_ms[i] = now;
465	          s_hold_fired[i] = false;
466	
467	          /* Only keys that carry a press-and-hold binding emit the edge
468	           * pair.  Firing it for every key made each tap of KEY1/KEY2 log
469	           * "unmapped" for PRESS and RELEASE before the TAP that mattered
470	           * (board: "我都是单击").  TAP/HOLD/DOUBLE/COMBO keep their
471	           * unmapped diagnostic -- those are gestures a person can
472	           * discover by accident, these are not.
473	           */
474	
475	          if (keymap_lookup(bit, GESTURE_PRESS, NULL) != NULL)
476	            {
477	              gesture_fire(bit, GESTURE_PRESS);
478	            }
479	        }
480	
481	      if ((s_combo_started & bit) != 0)
482	        {
483	          /* Consumed by the combo: no single-key gesture for this press, and
484	           * a tap left over from an earlier press of the same key must go
485	           * too -- otherwise it fires after the combo and looks like a stray
486	           * KEY1 tap.
487	           */
488	
489	          s_tap_pending[i] = false;
490	          if ((released & bit) != 0)
491	            {
492	              s_combo_started &= ~bit;
493	            }
494	
495	          continue;
496	        }
497	
498	      /* A key bound to GESTURE_PRESS is a press-and-hold key: the whole
499	       * gesture is the edge pair, so TAP and HOLD must not also fire or
500	       * releasing the PTT key would answer a permission request.
501	       */
502	
503	      if (keymap_lookup(bit, GESTURE_PRESS, NULL) == NULL)
504	        {
505	          if ((s_held & bit) != 0 && !s_hold_fired[i] &&
506	              (uint32_t)(now - s_down_ms[i]) >= GESTURE_HOLD_MS)
507	            {
508	              s_hold_fired[i] = true;
509	              s_tap_pending[i] = false;
510	              gesture_fire(bit, GESTURE_HOLD);
511	            }
512	
513	          if ((released & bit) != 0 && !s_hold_fired[i])
514	            {
515	              gesture_fire(bit, GESTURE_TAP);
516	            }
517	        }
518	
519	      if ((released & bit) != 0 &&
520	          keymap_lookup(bit, GESTURE_RELEASE, NULL) != NULL)
521	        {
522	          gesture_fire(bit, GESTURE_RELEASE);
523	        }
524	    }
525	
526	  /* Reset the combo only after the loop has seen every release edge.
527	   * Clearing it on s_held == 0 beforehand let the last key released skip
528	   * the suppression and emit a stray TAP.
529	   */
530	
531	  if (s_held == 0)
532	    {
533	      s_combo_started = 0;
534	    }
535	
536	  s_prev = s_held;
537	}
