627	/****************************************************************************
628	 * Public Functions
629	 ****************************************************************************/
630	
631	/* Tracks whether the approval context is currently on the stack so the poll
632	 * below only pushes/pops on a transition, not every slice. */
633	static bool s_approval_active;
634	
635	/* Switch the key context when a remote permission request comes and goes.
636	 * Polled once per slice: when pending() says an approval is up, the approval
637	 * map (S2 approve / S3 deny) is pushed over the idle map; when it clears, it
638	 * is popped and the keys go back to scrolling. */
639	static void update_pending_ctx(void)
640	{
641	  bool pending;
642	
643	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
644	  pending = (s_pending != NULL) && s_pending(s_ctx) != 0;
645	#else
646	  pending = false;
647	#endif
648	
649	  if (pending && !s_approval_active)
650	    {
651	      keyctx_push(&g_approval_ctx);
652	      s_approval_active = true;
653	    }
654	  else if (!pending && s_approval_active)
655	    {
656	      keyctx_pop();
657	      s_approval_active = false;
658	    }
659	}
660	
661	static FAR void *key_thread(FAR void *arg)
662	{
663	  (void)arg;
664	
665	  if (button_source_init() < 0)
666	    {
667	      return NULL;
668	    }
669	
670	  extern void bk7258_status_led_step(uint32_t tick_ms);
671	  unsigned int ticks = 0;
672	
673	  keyctx_push(&g_idle_ctx);
674	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
675	  remote_ctrl_register_input(&g_keymap_ops);
676	#endif
677	  printf("[key] input up (%d keys)\n", KEY_COUNT);
678	
679	  for (; ; )
680	    {
681	      update_pending_ctx();
682	      button_source_poll();
683	      if (++ticks >= LED_SLICE_TICKS)
684	        {
685	          ticks = 0;
686	          bk7258_status_led_step(POLL_SLICE_MS * LED_SLICE_TICKS);
687	        }
688	    }
689	
690	  return NULL;
691	}
